-- Insurance AI Database — Supabase Aligned
-- Contract version: im-health-assessment-2026-07-v1
-- Generated distribution: no psql meta-commands.
-- IMPORTANT: recommendation signals are draft and human_approved=false.
-- This SQL is for POC integration and does not constitute insurance advice or a quote.


-- BEGIN 001_extensions.sql
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS vector;

CREATE SCHEMA IF NOT EXISTS catalog;
CREATE SCHEMA IF NOT EXISTS knowledge;
CREATE SCHEMA IF NOT EXISTS intake;
CREATE SCHEMA IF NOT EXISTS recommendation;
CREATE SCHEMA IF NOT EXISTS lead;
CREATE SCHEMA IF NOT EXISTS audit;

COMMIT;
-- END 001_extensions.sql

-- BEGIN 002_schema.sql
BEGIN;

CREATE OR REPLACE FUNCTION catalog.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION knowledge.immutable_unaccent(input_text text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
STRICT
AS $$
  SELECT public.unaccent(input_text);
$$;

CREATE TABLE IF NOT EXISTS catalog.company (
  company_id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  company_type text NOT NULL DEFAULT 'Insurance',
  country_name text NOT NULL DEFAULT 'Ελλάδα',
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS catalog.product (
  product_id text PRIMARY KEY,
  company_id text NOT NULL REFERENCES catalog.company(company_id),
  name text NOT NULL,
  product_type text,
  category text,
  scope_text text,
  corpus_status text,
  critical_note text,
  version_label text,
  effective_from date,
  effective_to date,
  is_active boolean NOT NULL DEFAULT true,
  recommendation_scope boolean NOT NULL DEFAULT true,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (company_id, name)
);

CREATE TABLE IF NOT EXISTS catalog.service (
  service_id text PRIMARY KEY,
  company_id text NOT NULL REFERENCES catalog.company(company_id),
  name text NOT NULL,
  service_type text,
  description text,
  clarification text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS catalog.product_service (
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  service_id text NOT NULL REFERENCES catalog.service(service_id) ON DELETE CASCADE,
  availability_note text,
  PRIMARY KEY (product_id, service_id)
);

CREATE TABLE IF NOT EXISTS catalog.document (
  document_id text PRIMARY KEY,
  company_id text REFERENCES catalog.company(company_id),
  canonical_document_id text REFERENCES catalog.document(document_id),
  title text,
  primary_filename text NOT NULL,
  document_type text NOT NULL,
  version_label text,
  effective_from date,
  effective_to date,
  page_count integer CHECK (page_count IS NULL OR page_count >= 0),
  sha256 char(64),
  source_note text,
  corpus_status text,
  validation_status text NOT NULL DEFAULT 'unreviewed',
  is_historical boolean NOT NULL DEFAULT false,
  is_available boolean NOT NULL DEFAULT false,
  legacy_product_reference text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (canonical_document_id IS NULL OR canonical_document_id <> document_id)
);

CREATE TABLE IF NOT EXISTS catalog.document_alias (
  alias_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  document_id text NOT NULL REFERENCES catalog.document(document_id) ON DELETE CASCADE,
  original_filename text NOT NULL,
  sha256 char(64) NOT NULL,
  file_size_bytes bigint CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0),
  object_key text,
  is_primary boolean NOT NULL DEFAULT false,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (document_id, original_filename, sha256)
);

CREATE TABLE IF NOT EXISTS catalog.product_document (
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  document_id text NOT NULL REFERENCES catalog.document(document_id) ON DELETE CASCADE,
  relationship_type text NOT NULL DEFAULT 'source',
  PRIMARY KEY (product_id, document_id)
);

CREATE TABLE IF NOT EXISTS catalog.product_feature (
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  feature_key text NOT NULL,
  raw_value text,
  normalized_boolean boolean,
  source_note text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (product_id, feature_key)
);

CREATE TABLE IF NOT EXISTS catalog.coverage_fact (
  fact_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  category text,
  topic text NOT NULL,
  coverage_status text,
  term_analysis text NOT NULL,
  limit_frequency text,
  deductible_participation text,
  waiting_period_text text,
  geography text,
  network text,
  source_filename text,
  article_section text,
  confidence text,
  evidence_level text,
  human_validated boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS catalog.deductible_rule (
  deductible_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  coverage_case text NOT NULL,
  exact_rule text NOT NULL,
  practical_meaning text,
  period_frequency text,
  source_filename text,
  article_section text,
  confidence text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.monetary_fact (
  monetary_id text PRIMARY KEY,
  product_id text REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  legacy_product_reference text NOT NULL,
  exact_excerpt text NOT NULL,
  source_filename text,
  pdf_page integer CHECK (pdf_page IS NULL OR pdf_page > 0),
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.monetary_fact_product (
  monetary_id text NOT NULL REFERENCES catalog.monetary_fact(monetary_id) ON DELETE CASCADE,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  PRIMARY KEY (monetary_id, product_id)
);

CREATE TABLE IF NOT EXISTS catalog.waiting_period (
  waiting_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  coverage_case text NOT NULL,
  duration_text text NOT NULL,
  application_text text,
  source_filename text,
  article_section text,
  confidence text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.exclusion (
  exclusion_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  record_type text,
  exclusion_text text NOT NULL,
  source_filename text,
  pdf_page integer CHECK (pdf_page IS NULL OR pdf_page > 0),
  validation_note text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.provider_network (
  network_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  provider_type text,
  provider_name text NOT NULL,
  region text,
  network_status text,
  version_note text,
  valid_from date,
  valid_to date,
  last_verified_at timestamptz,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.medical_procedure (
  procedure_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  medical_specialty text,
  severity_category text,
  procedure_name text NOT NULL,
  pdf_page integer CHECK (pdf_page IS NULL OR pdf_page > 0),
  source_filename text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.procedure_fee (
  fee_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  fee_type text,
  medical_specialty text,
  severity_category text,
  amount numeric(14,2),
  currency text,
  source_filename text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.supplementary_benefit (
  benefit_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  benefit_name text NOT NULL,
  exact_operation_conditions text,
  waiting_text text,
  duration_expiry text,
  source_filename text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.assistance_benefit (
  assistance_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  service_id text REFERENCES catalog.service(service_id),
  legacy_service_id text,
  service_case text NOT NULL,
  exact_limit_benefit text,
  UNIQUE (legacy_service_id, service_case)
);

CREATE TABLE IF NOT EXISTS catalog.claim_rule (
  claim_rule_id text PRIMARY KEY,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  claim_case text NOT NULL,
  exact_process text,
  deadline_limit text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.product_change (
  change_id text PRIMARY KEY,
  product_id text REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  legacy_product_reference text NOT NULL,
  effective_date date,
  change_text text NOT NULL,
  source_filename text,
  human_validated boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS catalog.product_change_product (
  change_id text NOT NULL REFERENCES catalog.product_change(change_id) ON DELETE CASCADE,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  PRIMARY KEY (change_id, product_id)
);

CREATE TABLE IF NOT EXISTS catalog.evaluation_mapping (
  mapping_id text PRIMARY KEY,
  question_text text NOT NULL,
  answer_signal text,
  database_dimensions text,
  action_text text,
  is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS catalog.data_quality_issue (
  issue_id text PRIMARY KEY,
  scope_text text NOT NULL,
  issue_text text NOT NULL,
  cause_text text,
  required_action text,
  severity text NOT NULL,
  status text NOT NULL DEFAULT 'open',
  resolved_at timestamptz,
  resolution_note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (status IN ('open', 'accepted', 'resolved'))
);

CREATE TABLE IF NOT EXISTS knowledge.ingestion_run (
  ingestion_run_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_label text NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  status text NOT NULL DEFAULT 'running',
  details jsonb NOT NULL DEFAULT '{}'::jsonb,
  CHECK (status IN ('running', 'completed', 'failed', 'partial'))
);

CREATE TABLE IF NOT EXISTS knowledge.document_page (
  page_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  document_id text NOT NULL REFERENCES catalog.document(document_id) ON DELETE CASCADE,
  page_number integer NOT NULL CHECK (page_number > 0),
  categories text[] NOT NULL DEFAULT '{}'::text[],
  headings text[] NOT NULL DEFAULT '{}'::text[],
  content text NOT NULL,
  source_filename text,
  extraction_method text NOT NULL DEFAULT 'source_workbook',
  quality_flag text,
  content_sha256 char(64),
  search_vector tsvector GENERATED ALWAYS AS (
    to_tsvector('simple'::regconfig, knowledge.immutable_unaccent(coalesce(content, '')))
  ) STORED,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (document_id, page_number)
);

CREATE TABLE IF NOT EXISTS knowledge.document_page_product (
  page_id bigint NOT NULL REFERENCES knowledge.document_page(page_id) ON DELETE CASCADE,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  PRIMARY KEY (page_id, product_id)
);

CREATE TABLE IF NOT EXISTS knowledge.document_chunk (
  chunk_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id text NOT NULL REFERENCES catalog.document(document_id) ON DELETE CASCADE,
  chunk_ordinal integer NOT NULL CHECK (chunk_ordinal >= 0),
  page_start integer NOT NULL CHECK (page_start > 0),
  page_end integer NOT NULL CHECK (page_end >= page_start),
  heading text,
  content text NOT NULL,
  char_count integer GENERATED ALWAYS AS (length(content)) STORED,
  content_sha256 char(64) NOT NULL,
  embedding vector(1536),
  embedding_model text,
  search_vector tsvector GENERATED ALWAYS AS (
    to_tsvector(
      'simple'::regconfig,
      knowledge.immutable_unaccent(coalesce(heading, '') || ' ' || coalesce(content, ''))
    )
  ) STORED,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (document_id, chunk_ordinal)
);

CREATE TABLE IF NOT EXISTS knowledge.document_chunk_product (
  chunk_id uuid NOT NULL REFERENCES knowledge.document_chunk(chunk_id) ON DELETE CASCADE,
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  PRIMARY KEY (chunk_id, product_id)
);

CREATE TABLE IF NOT EXISTS intake.customer_session (
  session_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_reference text,
  locale text NOT NULL DEFAULT 'el-GR',
  status text NOT NULL DEFAULT 'active',
  privacy_notice_version text NOT NULL,
  privacy_notice_accepted_at timestamptz NOT NULL,
  health_data_consent boolean NOT NULL DEFAULT false,
  health_data_consent_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  deleted_at timestamptz,
  CHECK (status IN ('active', 'completed', 'expired', 'withdrawn')),
  CHECK (NOT health_data_consent OR health_data_consent_at IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS intake.question (
  question_id text PRIMARY KEY,
  question_text text NOT NULL,
  answer_type text NOT NULL,
  sensitivity_level text NOT NULL DEFAULT 'ordinary',
  required boolean NOT NULL DEFAULT false,
  display_order integer NOT NULL,
  validation_rule jsonb NOT NULL DEFAULT '{}'::jsonb,
  is_active boolean NOT NULL DEFAULT true,
  CHECK (sensitivity_level IN ('ordinary', 'financial', 'health'))
);

CREATE TABLE IF NOT EXISTS intake.question_option (
  option_id text PRIMARY KEY,
  question_id text NOT NULL REFERENCES intake.question(question_id) ON DELETE CASCADE,
  label text NOT NULL,
  value jsonb NOT NULL,
  display_order integer NOT NULL,
  is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS intake.question_response (
  response_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES intake.customer_session(session_id) ON DELETE CASCADE,
  question_id text NOT NULL REFERENCES intake.question(question_id),
  answer_value jsonb NOT NULL,
  answered_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (session_id, question_id)
);

CREATE TABLE IF NOT EXISTS recommendation.ruleset (
  ruleset_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  version text NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  effective_from timestamptz,
  effective_to timestamptz,
  approved_by text,
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (name, version),
  CHECK (status IN ('draft', 'approved', 'retired'))
);

CREATE TABLE IF NOT EXISTS recommendation.scoring_rule (
  rule_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ruleset_id uuid NOT NULL REFERENCES recommendation.ruleset(ruleset_id) ON DELETE CASCADE,
  rule_code text NOT NULL,
  description text NOT NULL,
  priority integer NOT NULL DEFAULT 100,
  rule_kind text NOT NULL,
  conditions jsonb NOT NULL,
  outcome jsonb NOT NULL,
  source_note text,
  human_approved boolean NOT NULL DEFAULT false,
  UNIQUE (ruleset_id, rule_code),
  CHECK (rule_kind IN ('eligibility', 'exclusion', 'score', 'warning'))
);

CREATE TABLE IF NOT EXISTS recommendation.run (
  recommendation_run_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES intake.customer_session(session_id),
  ruleset_id uuid REFERENCES recommendation.ruleset(ruleset_id),
  status text NOT NULL DEFAULT 'running',
  model_name text,
  model_version text,
  prompt_version text,
  input_snapshot jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  reviewed_by text,
  reviewed_at timestamptz,
  CHECK (status IN ('running', 'completed', 'failed', 'needs_review', 'reviewed'))
);

CREATE TABLE IF NOT EXISTS recommendation.candidate (
  candidate_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recommendation_run_id uuid NOT NULL REFERENCES recommendation.run(recommendation_run_id) ON DELETE CASCADE,
  product_id text NOT NULL REFERENCES catalog.product(product_id),
  eligible boolean NOT NULL,
  score numeric(9,4),
  rank integer,
  reason_codes jsonb NOT NULL DEFAULT '[]'::jsonb,
  warnings jsonb NOT NULL DEFAULT '[]'::jsonb,
  explanation text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (recommendation_run_id, product_id)
);

CREATE TABLE IF NOT EXISTS recommendation.evidence (
  evidence_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  candidate_id uuid NOT NULL REFERENCES recommendation.candidate(candidate_id) ON DELETE CASCADE,
  fact_id text REFERENCES catalog.coverage_fact(fact_id),
  chunk_id uuid REFERENCES knowledge.document_chunk(chunk_id),
  claim_text text NOT NULL,
  citation_label text,
  relevance numeric(7,6),
  CHECK (fact_id IS NOT NULL OR chunk_id IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS lead.request (
  lead_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES intake.customer_session(session_id),
  recommendation_run_id uuid REFERENCES recommendation.run(recommendation_run_id),
  partner_reference text,
  contact_payload_encrypted bytea NOT NULL,
  encryption_key_version text NOT NULL,
  consent_to_contact boolean NOT NULL,
  consent_text_version text NOT NULL,
  consent_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'new',
  created_at timestamptz NOT NULL DEFAULT now(),
  assigned_at timestamptz,
  closed_at timestamptz,
  CHECK (consent_to_contact),
  CHECK (status IN ('new', 'assigned', 'contacted', 'qualified', 'closed', 'deleted'))
);

CREATE TABLE IF NOT EXISTS audit.event (
  audit_event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  actor_type text NOT NULL,
  actor_reference text,
  event_type text NOT NULL,
  entity_type text NOT NULL,
  entity_reference text,
  correlation_id uuid,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE OR REPLACE FUNCTION audit.reject_event_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'audit.event is append-only';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger WHERE tgname = 'audit_event_append_only'
  ) THEN
    CREATE TRIGGER audit_event_append_only
    BEFORE UPDATE OR DELETE ON audit.event
    FOR EACH ROW EXECUTE FUNCTION audit.reject_event_mutation();
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_product_company ON catalog.product(company_id);
CREATE INDEX IF NOT EXISTS idx_product_active_scope ON catalog.product(is_active, recommendation_scope);
CREATE INDEX IF NOT EXISTS idx_document_company ON catalog.document(company_id);
CREATE INDEX IF NOT EXISTS idx_document_sha256 ON catalog.document(sha256) WHERE sha256 IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_document_alias_sha256 ON catalog.document_alias(sha256);
CREATE INDEX IF NOT EXISTS idx_coverage_fact_product_category ON catalog.coverage_fact(product_id, category);
CREATE INDEX IF NOT EXISTS idx_waiting_period_product ON catalog.waiting_period(product_id);
CREATE INDEX IF NOT EXISTS idx_exclusion_product ON catalog.exclusion(product_id);
CREATE INDEX IF NOT EXISTS idx_network_product_region ON catalog.provider_network(product_id, region);
CREATE INDEX IF NOT EXISTS idx_procedure_product_specialty ON catalog.medical_procedure(product_id, medical_specialty);
CREATE INDEX IF NOT EXISTS idx_document_page_document_page ON knowledge.document_page(document_id, page_number);
CREATE INDEX IF NOT EXISTS idx_document_page_search ON knowledge.document_page USING gin(search_vector);
CREATE INDEX IF NOT EXISTS idx_document_chunk_search ON knowledge.document_chunk USING gin(search_vector);
CREATE INDEX IF NOT EXISTS idx_document_chunk_embedding ON knowledge.document_chunk USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_session_expiry ON intake.customer_session(expires_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_recommendation_run_session ON recommendation.run(session_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_candidate_run_rank ON recommendation.candidate(recommendation_run_id, rank);
CREATE INDEX IF NOT EXISTS idx_audit_correlation ON audit.event(correlation_id, occurred_at);

DO $$
DECLARE
  table_name text;
BEGIN
  FOREACH table_name IN ARRAY ARRAY[
    'company', 'product', 'service', 'document', 'coverage_fact', 'data_quality_issue'
  ] LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM pg_trigger
      WHERE tgname = 'set_updated_at_' || table_name
    ) THEN
      EXECUTE format(
        'CREATE TRIGGER %I BEFORE UPDATE ON catalog.%I FOR EACH ROW EXECUTE FUNCTION catalog.set_updated_at()',
        'set_updated_at_' || table_name,
        table_name
      );
    END IF;
  END LOOP;
END;
$$;

COMMIT;
-- END 002_schema.sql

-- BEGIN 003_views_and_search.sql
BEGIN;

CREATE OR REPLACE VIEW catalog.v_product_summary AS
SELECT
  p.product_id,
  p.name AS product_name,
  p.product_type,
  p.category,
  p.scope_text,
  p.corpus_status,
  p.critical_note,
  p.is_active,
  p.recommendation_scope,
  c.company_id,
  c.name AS company_name,
  count(DISTINCT cf.fact_id) AS coverage_fact_count,
  count(DISTINCT pd.document_id) AS document_count,
  array_remove(array_agg(DISTINCT cf.category ORDER BY cf.category), NULL) AS coverage_categories
FROM catalog.product p
JOIN catalog.company c ON c.company_id = p.company_id
LEFT JOIN catalog.coverage_fact cf ON cf.product_id = p.product_id
LEFT JOIN catalog.product_document pd ON pd.product_id = p.product_id
GROUP BY
  p.product_id, p.name, p.product_type, p.category, p.scope_text,
  p.corpus_status, p.critical_note, p.is_active, p.recommendation_scope,
  c.company_id, c.name;

CREATE OR REPLACE VIEW catalog.v_product_evidence_completeness AS
SELECT
  p.product_id,
  p.name AS product_name,
  count(DISTINCT cf.fact_id) AS coverage_facts,
  count(DISTINCT wp.waiting_id) AS waiting_periods,
  count(DISTINCT ex.exclusion_id) AS exclusions,
  count(DISTINCT dr.deductible_id) AS deductible_rules,
  count(DISTINCT pd.document_id) AS linked_documents,
  count(DISTINCT CASE WHEN d.is_available THEN d.document_id END) AS available_documents,
  bool_or(coalesce(cf.human_validated, false)) AS has_validated_fact,
  CASE
    WHEN count(DISTINCT cf.fact_id) = 0 THEN 'insufficient'
    WHEN count(DISTINCT pd.document_id) = 0 THEN 'insufficient'
    WHEN count(DISTINCT CASE WHEN d.is_available THEN d.document_id END) = 0 THEN 'source_missing'
    WHEN NOT bool_or(coalesce(cf.human_validated, false)) THEN 'needs_human_validation'
    ELSE 'ready'
  END AS readiness_status
FROM catalog.product p
LEFT JOIN catalog.coverage_fact cf ON cf.product_id = p.product_id
LEFT JOIN catalog.waiting_period wp ON wp.product_id = p.product_id
LEFT JOIN catalog.exclusion ex ON ex.product_id = p.product_id
LEFT JOIN catalog.deductible_rule dr ON dr.product_id = p.product_id
LEFT JOIN catalog.product_document pd ON pd.product_id = p.product_id
LEFT JOIN catalog.document d ON d.document_id = pd.document_id
GROUP BY p.product_id, p.name;

CREATE OR REPLACE VIEW catalog.v_current_documents AS
SELECT
  d.document_id,
  d.company_id,
  d.title,
  d.primary_filename,
  d.document_type,
  d.version_label,
  d.effective_from,
  d.effective_to,
  d.page_count,
  d.sha256,
  d.validation_status,
  d.is_available,
  array_remove(array_agg(DISTINCT pd.product_id ORDER BY pd.product_id), NULL) AS product_ids
FROM catalog.document d
LEFT JOIN catalog.product_document pd ON pd.document_id = d.document_id
WHERE d.canonical_document_id IS NULL
  AND NOT d.is_historical
  AND (d.effective_to IS NULL OR d.effective_to >= current_date)
GROUP BY d.document_id;

CREATE OR REPLACE FUNCTION knowledge.search_chunks_lexical(
  p_query text,
  p_product_ids text[] DEFAULT NULL,
  p_limit integer DEFAULT 12
)
RETURNS TABLE (
  chunk_id uuid,
  product_id text,
  product_name text,
  document_id text,
  document_title text,
  page_start integer,
  page_end integer,
  heading text,
  content text,
  lexical_score real,
  citation_label text
)
LANGUAGE sql
STABLE
AS $$
  WITH q AS (
    SELECT websearch_to_tsquery(
      'simple'::regconfig,
      knowledge.immutable_unaccent(coalesce(p_query, ''))
    ) AS query
  )
  SELECT
    ch.chunk_id,
    cp.product_id,
    p.name,
    ch.document_id,
    coalesce(d.title, d.primary_filename),
    ch.page_start,
    ch.page_end,
    ch.heading,
    ch.content,
    ts_rank_cd(ch.search_vector, q.query)::real AS lexical_score,
    format(
      '%s, σελ. %s%s',
      coalesce(d.title, d.primary_filename),
      ch.page_start,
      CASE WHEN ch.page_end > ch.page_start THEN '-' || ch.page_end::text ELSE '' END
    ) AS citation_label
  FROM knowledge.document_chunk ch
  JOIN knowledge.document_chunk_product cp ON cp.chunk_id = ch.chunk_id
  JOIN catalog.product p ON p.product_id = cp.product_id
  JOIN catalog.document d ON d.document_id = ch.document_id
  CROSS JOIN q
  WHERE ch.search_vector @@ q.query
    AND (p_product_ids IS NULL OR cp.product_id = ANY (p_product_ids))
  ORDER BY lexical_score DESC, ch.document_id, ch.chunk_ordinal
  LIMIT greatest(1, least(coalesce(p_limit, 12), 100));
$$;

CREATE OR REPLACE FUNCTION knowledge.search_chunks_hybrid(
  p_query text,
  p_query_embedding vector(1536),
  p_product_ids text[] DEFAULT NULL,
  p_limit integer DEFAULT 12,
  p_semantic_weight real DEFAULT 0.65
)
RETURNS TABLE (
  chunk_id uuid,
  product_id text,
  product_name text,
  document_id text,
  document_title text,
  page_start integer,
  page_end integer,
  heading text,
  content text,
  lexical_score real,
  semantic_score real,
  hybrid_score real,
  citation_label text
)
LANGUAGE sql
STABLE
AS $$
  WITH q AS (
    SELECT websearch_to_tsquery(
      'simple'::regconfig,
      knowledge.immutable_unaccent(coalesce(p_query, ''))
    ) AS query
  ), scored AS (
    SELECT
      ch.chunk_id,
      cp.product_id,
      p.name AS product_name,
      ch.document_id,
      coalesce(d.title, d.primary_filename) AS document_title,
      ch.page_start,
      ch.page_end,
      ch.heading,
      ch.content,
      ts_rank_cd(ch.search_vector, q.query)::real AS lexical_score,
      CASE
        WHEN ch.embedding IS NULL OR p_query_embedding IS NULL THEN 0::real
        ELSE (1 - (ch.embedding <=> p_query_embedding))::real
      END AS semantic_score,
      format(
        '%s, σελ. %s%s',
        coalesce(d.title, d.primary_filename),
        ch.page_start,
        CASE WHEN ch.page_end > ch.page_start THEN '-' || ch.page_end::text ELSE '' END
      ) AS citation_label
    FROM knowledge.document_chunk ch
    JOIN knowledge.document_chunk_product cp ON cp.chunk_id = ch.chunk_id
    JOIN catalog.product p ON p.product_id = cp.product_id
    JOIN catalog.document d ON d.document_id = ch.document_id
    CROSS JOIN q
    WHERE (p_product_ids IS NULL OR cp.product_id = ANY (p_product_ids))
      AND (ch.embedding IS NOT NULL OR ch.search_vector @@ q.query)
  )
  SELECT
    s.chunk_id,
    s.product_id,
    s.product_name,
    s.document_id,
    s.document_title,
    s.page_start,
    s.page_end,
    s.heading,
    s.content,
    s.lexical_score,
    s.semantic_score,
    (
      greatest(0, least(1, coalesce(p_semantic_weight, 0.65))) * s.semantic_score
      + (1 - greatest(0, least(1, coalesce(p_semantic_weight, 0.65)))) * s.lexical_score
    )::real AS hybrid_score,
    s.citation_label
  FROM scored s
  ORDER BY hybrid_score DESC, s.document_id, s.page_start
  LIMIT greatest(1, least(coalesce(p_limit, 12), 100));
$$;

COMMIT;
-- END 003_views_and_search.sql

-- BEGIN 005_app_contract.sql
BEGIN;

CREATE SCHEMA IF NOT EXISTS app_api;

ALTER TABLE intake.question
  ADD COLUMN IF NOT EXISTS step_code text,
  ADD COLUMN IF NOT EXISTS help_text text,
  ADD COLUMN IF NOT EXISTS max_selections integer,
  ADD COLUMN IF NOT EXISTS conditional_visibility jsonb NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS ui_metadata jsonb NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE intake.question_option
  ADD COLUMN IF NOT EXISTS signal_metadata jsonb NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE catalog.evaluation_mapping
  ADD COLUMN IF NOT EXISTS question_id text,
  ADD COLUMN IF NOT EXISTS option_value text,
  ADD COLUMN IF NOT EXISTS signal_code text,
  ADD COLUMN IF NOT EXISTS weight numeric(8,4),
  ADD COLUMN IF NOT EXISTS mapping_status text NOT NULL DEFAULT 'draft',
  ADD COLUMN IF NOT EXISTS requires_human_approval boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS intake.assessment_submission (
  submission_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL UNIQUE REFERENCES intake.customer_session(session_id) ON DELETE CASCADE,
  schema_version text NOT NULL,
  answers jsonb NOT NULL,
  generated_profile jsonb NOT NULL DEFAULT '{}'::jsonb,
  upload_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'completed',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  CHECK (jsonb_typeof(answers) = 'object'),
  CHECK (jsonb_typeof(generated_profile) = 'object'),
  CHECK (jsonb_typeof(upload_metadata) = 'object'),
  CHECK (status IN ('draft', 'completed', 'withdrawn', 'deleted'))
);

CREATE TABLE IF NOT EXISTS recommendation.signal_definition (
  signal_code text PRIMARY KEY,
  name text NOT NULL,
  description text NOT NULL,
  signal_kind text NOT NULL DEFAULT 'score',
  default_weight numeric(8,4) NOT NULL DEFAULT 1,
  database_dimensions jsonb NOT NULL DEFAULT '[]'::jsonb,
  evidence_requirements jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'draft',
  requires_human_approval boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (signal_kind IN ('score', 'segment', 'filter', 'warning_only')),
  CHECK (status IN ('draft', 'approved', 'retired')),
  CHECK (default_weight >= 0)
);

CREATE TABLE IF NOT EXISTS recommendation.option_signal (
  question_id text NOT NULL REFERENCES intake.question(question_id) ON DELETE CASCADE,
  option_value text NOT NULL,
  signal_code text NOT NULL REFERENCES recommendation.signal_definition(signal_code) ON DELETE CASCADE,
  weight numeric(8,4) NOT NULL DEFAULT 1,
  reason_template text,
  status text NOT NULL DEFAULT 'draft',
  human_approved boolean NOT NULL DEFAULT false,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (question_id, option_value, signal_code),
  CHECK (weight >= 0),
  CHECK (status IN ('draft', 'approved', 'retired'))
);

CREATE TABLE IF NOT EXISTS recommendation.product_signal (
  product_id text NOT NULL REFERENCES catalog.product(product_id) ON DELETE CASCADE,
  signal_code text NOT NULL REFERENCES recommendation.signal_definition(signal_code) ON DELETE CASCADE,
  score numeric(6,2) NOT NULL,
  confidence text NOT NULL DEFAULT 'low',
  basis text NOT NULL,
  evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
  source_method text NOT NULL DEFAULT 'generated_draft_v1',
  status text NOT NULL DEFAULT 'draft',
  human_approved boolean NOT NULL DEFAULT false,
  reviewed_by text,
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (product_id, signal_code),
  CHECK (score >= 0 AND score <= 100),
  CHECK (confidence IN ('low', 'medium', 'high')),
  CHECK (status IN ('draft', 'approved', 'retired')),
  CHECK (jsonb_typeof(evidence) = 'array')
);

CREATE TABLE IF NOT EXISTS lead.advisor_handoff (
  handoff_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  lead_id uuid NOT NULL UNIQUE REFERENCES lead.request(lead_id) ON DELETE CASCADE,
  schema_version text NOT NULL,
  summary jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (jsonb_typeof(summary) = 'object')
);

CREATE OR REPLACE FUNCTION intake.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'assessment_submission_set_updated_at') THEN
    CREATE TRIGGER assessment_submission_set_updated_at
    BEFORE UPDATE ON intake.assessment_submission
    FOR EACH ROW EXECUTE FUNCTION intake.set_updated_at();
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'signal_definition_set_updated_at') THEN
    CREATE TRIGGER signal_definition_set_updated_at
    BEFORE UPDATE ON recommendation.signal_definition
    FOR EACH ROW EXECUTE FUNCTION intake.set_updated_at();
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'product_signal_set_updated_at') THEN
    CREATE TRIGGER product_signal_set_updated_at
    BEFORE UPDATE ON recommendation.product_signal
    FOR EACH ROW EXECUTE FUNCTION intake.set_updated_at();
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'advisor_handoff_set_updated_at') THEN
    CREATE TRIGGER advisor_handoff_set_updated_at
    BEFORE UPDATE ON lead.advisor_handoff
    FOR EACH ROW EXECUTE FUNCTION intake.set_updated_at();
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_assessment_submission_session_status
  ON intake.assessment_submission(session_id, status);
CREATE INDEX IF NOT EXISTS idx_option_signal_signal
  ON recommendation.option_signal(signal_code, status);
CREATE INDEX IF NOT EXISTS idx_product_signal_signal_score
  ON recommendation.product_signal(signal_code, score DESC)
  WHERE status <> 'retired';

CREATE OR REPLACE VIEW recommendation.product_evidence_corpus AS
SELECT
  p.product_id,
  p.name AS product_name,
  p.company_id,
  lower(knowledge.immutable_unaccent(concat_ws(' ',
    p.name,
    p.product_type,
    p.category,
    p.scope_text,
    p.critical_note,
    cov.corpus,
    ded.corpus,
    wait.corpus,
    net.corpus,
    claim.corpus,
    supp.corpus,
    svc.corpus
  ))) AS corpus,
  coalesce(cov.record_count, 0) AS coverage_count,
  coalesce(ded.record_count, 0) AS deductible_count,
  coalesce(wait.record_count, 0) AS waiting_count,
  coalesce(net.record_count, 0) AS network_count,
  coalesce(claim.record_count, 0) AS claim_rule_count
FROM catalog.product p
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', category, topic, coverage_status, term_analysis, limit_frequency,
      deductible_participation, waiting_period_text, geography, network), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.coverage_fact f
  WHERE f.product_id = p.product_id
) cov ON true
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', coverage_case, exact_rule, practical_meaning, period_frequency), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.deductible_rule d
  WHERE d.product_id = p.product_id
) ded ON true
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', coverage_case, duration_text, application_text), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.waiting_period w
  WHERE w.product_id = p.product_id
) wait ON true
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', provider_type, provider_name, region, network_status, version_note), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.provider_network n
  WHERE n.product_id = p.product_id
) net ON true
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', claim_case, exact_process, deadline_limit), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.claim_rule c
  WHERE c.product_id = p.product_id
) claim ON true
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', benefit_name, exact_operation_conditions, waiting_text, duration_expiry), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.supplementary_benefit s
  WHERE s.product_id = p.product_id
) supp ON true
LEFT JOIN LATERAL (
  SELECT
    string_agg(concat_ws(' ', sv.name, sv.description, sv.clarification, ps.availability_note), ' ') AS corpus,
    count(*)::integer AS record_count
  FROM catalog.product_service ps
  JOIN catalog.service sv USING (service_id)
  WHERE ps.product_id = p.product_id
) svc ON true
WHERE p.is_active AND p.recommendation_scope;

CREATE OR REPLACE FUNCTION recommendation.collect_evidence(
  p_product_id text,
  p_terms text[],
  p_limit integer DEFAULT 5
)
RETURNS jsonb
LANGUAGE sql
STABLE
SET search_path = pg_catalog, catalog, knowledge, recommendation
AS $$
  WITH evidence_rows AS (
    SELECT
      10 AS priority,
      f.fact_id AS evidence_id,
      'coverage_fact'::text AS evidence_type,
      f.topic AS title,
      f.term_analysis AS excerpt,
      f.source_filename,
      f.article_section,
      NULL::integer AS pdf_page
    FROM catalog.coverage_fact f
    WHERE f.product_id = p_product_id
      AND EXISTS (
        SELECT 1
        FROM unnest(p_terms) term
        WHERE lower(knowledge.immutable_unaccent(concat_ws(' ', f.category, f.topic, f.term_analysis,
          f.deductible_participation, f.waiting_period_text, f.geography, f.network)))
          LIKE '%' || term || '%'
      )

    UNION ALL

    SELECT
      20,
      d.deductible_id,
      'deductible_rule',
      d.coverage_case,
      concat_ws(' ', d.exact_rule, d.practical_meaning),
      d.source_filename,
      d.article_section,
      NULL::integer
    FROM catalog.deductible_rule d
    WHERE d.product_id = p_product_id
      AND EXISTS (
        SELECT 1
        FROM unnest(p_terms) term
        WHERE lower(knowledge.immutable_unaccent(concat_ws(' ', d.coverage_case, d.exact_rule, d.practical_meaning)))
          LIKE '%' || term || '%'
      )

    UNION ALL

    SELECT
      30,
      w.waiting_id,
      'waiting_period',
      w.coverage_case,
      concat_ws(' ', w.duration_text, w.application_text),
      w.source_filename,
      w.article_section,
      NULL::integer
    FROM catalog.waiting_period w
    WHERE w.product_id = p_product_id
      AND EXISTS (
        SELECT 1
        FROM unnest(p_terms) term
        WHERE lower(knowledge.immutable_unaccent(concat_ws(' ', w.coverage_case, w.duration_text, w.application_text)))
          LIKE '%' || term || '%'
      )

    UNION ALL

    SELECT
      40,
      c.claim_rule_id,
      'claim_rule',
      c.claim_case,
      concat_ws(' ', c.exact_process, c.deadline_limit),
      NULL::text,
      NULL::text,
      NULL::integer
    FROM catalog.claim_rule c
    WHERE c.product_id = p_product_id
      AND EXISTS (
        SELECT 1
        FROM unnest(p_terms) term
        WHERE lower(knowledge.immutable_unaccent(concat_ws(' ', c.claim_case, c.exact_process, c.deadline_limit)))
          LIKE '%' || term || '%'
      )
  ), limited AS (
    SELECT *
    FROM evidence_rows
    ORDER BY priority, evidence_id
    LIMIT greatest(1, least(coalesce(p_limit, 5), 20))
  )
  SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'type', evidence_type,
    'id', evidence_id,
    'title', title,
    'excerpt', excerpt,
    'source_filename', source_filename,
    'article_section', article_section,
    'pdf_page', pdf_page
  )) ORDER BY priority, evidence_id), '[]'::jsonb)
  FROM limited;
$$;

CREATE OR REPLACE FUNCTION app_api.assessment_contract()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, intake
AS $$
  SELECT jsonb_build_object(
    'schema_version', 'im-health-assessment-2026-07-v1',
    'questions', coalesce(jsonb_agg(question_payload ORDER BY display_order), '[]'::jsonb)
  )
  FROM (
    SELECT
      q.display_order,
      jsonb_strip_nulls(jsonb_build_object(
        'question_id', q.question_id,
        'step_code', q.step_code,
        'question_text', q.question_text,
        'help_text', q.help_text,
        'answer_type', q.answer_type,
        'sensitivity_level', q.sensitivity_level,
        'required', q.required,
        'max_selections', q.max_selections,
        'validation_rule', q.validation_rule,
        'conditional_visibility', q.conditional_visibility,
        'ui_metadata', q.ui_metadata,
        'options', coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'option_id', o.option_id,
            'label', o.label,
            'value', o.value,
            'display_order', o.display_order,
            'signal_metadata', o.signal_metadata
          ) ORDER BY o.display_order)
          FROM intake.question_option o
          WHERE o.question_id = q.question_id AND o.is_active
        ), '[]'::jsonb)
      )) AS question_payload
    FROM intake.question q
    WHERE q.is_active
  ) active_questions;
$$;

COMMIT;
-- END 005_app_contract.sql

