INSERT INTO catalog.product_feature (product_id, feature_key, raw_value, normalized_boolean, source_note) VALUES
  ('GEN-MP', 'greece', 'Υπό αναμονή: Ασθένεια καλύπτεται 30 ημέρες μετά την έναρξη για Ελλάδα και 180 ημέρες για εξωτερικό. Ατύχημα από την 1η ημέρα. | Αναμονή: 30 ημέρες Ελλάδα / 180 ημέρες εξωτερικό / Καλύπτεται: 100% των αναγνωρισμένων εξόδων μόνο σε Συνεργαζόμενο Νοσοκομείο, μέχρι το όριο και μετά την τυχόν συμμετοχή. | Όριο: Πίνακας Παροχών | Συμμετοχή: Πίνακας Παροχών / Καλύπτεται: Σε συνεργαζόμενα σημεία. Μετά την εξάντληση του ορίου, ο ασφαλισμένος πληρώνει με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου. | Όριο: Πίνακας Παροχών | Συμμετοχή: Μετά το όριο: ιδία πληρωμή με 30% έκπτωση', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'abroad', 'Υπό αναμονή: Ασθένεια καλύπτεται 30 ημέρες μετά την έναρξη για Ελλάδα και 180 ημέρες για εξωτερικό. Ατύχημα από την 1η ημέρα. | Αναμονή: 30 ημέρες Ελλάδα / 180 ημέρες εξωτερικό / Καλύπτεται: 100% εκτός ΗΠΑ/Καναδά και 90% σε ΗΠΑ/Καναδά, με χρήση ασφαλιστικού φορέα και τις προβλεπόμενες θεωρήσεις/μεταφράσεις. | Όριο: Πίνακας Παροχών | Συμμετοχή: Πίνακας Παροχών', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'one_day_clinic', 'Καλύπτεται: Μόνο σε Συνεργαζόμενο Νοσοκομείο. Απευθείας κάλυψη έως το όριο. Ο ασφαλισμένος πληρώνει το ποσοστό συμμετοχής, με ανώτατο όριο το ποσό της συμμετοχής του. | Όριο: Πίνακας Παροχών | Συμμετοχή: Ποσοστό + ανώτατο ποσό στον Πίνακα Παροχών', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'emergency', 'Καλύπτεται: Πρώτες βοήθειες στα εξωτερικά ιατρεία Συνεργαζόμενου Νοσοκομείου λόγω ασθένειας ή ατυχήματος. | Όριο: Πίνακας Παροχών | Συμμετοχή: Συμμετοχή στον Πίνακα Παροχών', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'icu', 'Καλύπτεται: Καλύπτονται έξοδα ΜΕΘ και ΜΑΦ ανεξάρτητα από τη θέση νοσηλείας. | Όριο: Πίνακας Παροχών | Συμμετοχή: Πίνακας Παροχών', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'chemotherapy', 'Καλύπτεται: Καλύπτονται αναγνωρισμένα έξοδα πριν ή μετά από νοσηλεία λόγω ασθένειας. | Όριο: Πίνακας Παροχών | Συμμετοχή: Πίνακας Παροχών', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'physiotherapy', 'Καλύπτεται: Με παραπεμπτικό. Μετά την εξάντληση του ορίου, ιδία πληρωμή με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου. | Όριο: Πίνακας Παροχών | Συμμετοχή: Μετά το όριο: 30% έκπτωση', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'check_up', 'Καλύπτεται: Πακέτα προληπτικών ελέγχων με συμμετοχή στον Πίνακα Παροχών. | Όριο: Σύμφωνα με πακέτο | Συμμετοχή: Πίνακας Παροχών | Αναμονή: 6 μήνες / Υπό αναμονή: Διατίθεται σε ασφαλισμένο άνω των 18 ετών μετά από ένα ασφαλιστικό έτος. | Όριο: Σύμφωνα με πακέτο | Συμμετοχή: Πίνακας Παροχών | Αναμονή: 1 ασφαλιστικό έτος', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'diagnostics', 'Καλύπτεται: Σε συνεργαζόμενα σημεία. Μετά την εξάντληση του ορίου, ο ασφαλισμένος πληρώνει με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου. | Όριο: Πίνακας Παροχών | Συμμετοχή: Μετά το όριο: ιδία πληρωμή με 30% έκπτωση', TRUE, '06_Πλέγμα'),
  ('GEN-MP', 'preventive', 'Καλύπτεται: Πακέτα προληπτικών ελέγχων με συμμετοχή στον Πίνακα Παροχών. | Όριο: Σύμφωνα με πακέτο | Συμμετοχή: Πίνακας Παροχών | Αναμονή: 6 μήνες / Υπό αναμονή: Διατίθεται σε ασφαλισμένο άνω των 18 ετών μετά από ένα ασφαλιστικό έτος. | Όριο: Σύμφωνα με πακέτο | Συμμετοχή: Πίνακας Παροχών | Αναμονή: 1 ασφαλιστικό έτος', TRUE, '06_Πλέγμα'),
