INSERT INTO catalog.coverage_fact (fact_id, product_id, category, topic, coverage_status, term_analysis, limit_frequency, deductible_participation, waiting_period_text, geography, network, source_filename, article_section, confidence, evidence_level) VALUES
  ('FACT-0001', 'GEN-MP', 'Eligibility', 'Προστατευόμενα παιδιά', 'Καλύπτεται', 'Άγαμα παιδιά από 30 ημερών έως 18 ετών ή έως 25 ετών εφόσον σπουδάζουν.', '30 ημέρες-18/25 έτη', NULL, NULL, NULL, NULL, 'Όροι Medical Prime.pdf', 'Ορισμοί', 'Υψηλή', 'Product'),
  ('FACT-0002', 'GEN-MP', 'Waiting', 'Γενική έναρξη ασθένειας', 'Υπό αναμονή', 'Ασθένεια καλύπτεται 30 ημέρες μετά την έναρξη για Ελλάδα και 180 ημέρες για εξωτερικό. Ατύχημα από την 1η ημέρα.', NULL, NULL, '30 ημέρες Ελλάδα / 180 ημέρες εξωτερικό', 'Ελλάδα/Εξωτερικό', NULL, 'Όροι Medical Prime.pdf', 'Γενικοί όροι', 'Υψηλή', 'Product'),
  ('FACT-0003', 'GEN-MP', 'Hospitalization', 'Νοσηλεία στην Ελλάδα', 'Καλύπτεται', '100% των αναγνωρισμένων εξόδων μόνο σε Συνεργαζόμενο Νοσοκομείο, μέχρι το όριο και μετά την τυχόν συμμετοχή.', 'Πίνακας Παροχών', 'Πίνακας Παροχών', NULL, 'Ελλάδα', 'Generali συνεργαζόμενα', 'Όροι Medical Prime.pdf', 'Άρθρο 4', 'Υψηλή', 'Product'),
  ('FACT-0004', 'GEN-MP', 'Abroad', 'Νοσηλεία στο εξωτερικό', 'Καλύπτεται', '100% εκτός ΗΠΑ/Καναδά και 90% σε ΗΠΑ/Καναδά, με χρήση ασφαλιστικού φορέα και τις προβλεπόμενες θεωρήσεις/μεταφράσεις.', 'Πίνακας Παροχών', 'Πίνακας Παροχών', NULL, 'Εξωτερικό', NULL, 'Όροι Medical Prime.pdf', 'Νοσηλεία στο Εξωτερικό', 'Υψηλή', 'Product'),
  ('FACT-0005', 'GEN-MP', 'One Day', 'One Day Surgery & One Day Clinic', 'Καλύπτεται', 'Μόνο σε Συνεργαζόμενο Νοσοκομείο. Απευθείας κάλυψη έως το όριο. Ο ασφαλισμένος πληρώνει το ποσοστό συμμετοχής, με ανώτατο όριο το ποσό της συμμετοχής του.', 'Πίνακας Παροχών', 'Ποσοστό + ανώτατο ποσό στον Πίνακα Παροχών', NULL, 'Ελλάδα', 'Generali συνεργαζόμενα', 'Όροι Medical Prime.pdf', 'One Day', 'Υψηλή', 'Product'),
  ('FACT-0006', 'GEN-MP', 'Emergency', 'Έκτακτα / επείγοντα', 'Καλύπτεται', 'Πρώτες βοήθειες στα εξωτερικά ιατρεία Συνεργαζόμενου Νοσοκομείου λόγω ασθένειας ή ατυχήματος.', 'Πίνακας Παροχών', 'Συμμετοχή στον Πίνακα Παροχών', NULL, 'Ελλάδα', 'Generali συνεργαζόμενα', 'Όροι Medical Prime.pdf', 'Emergency', 'Υψηλή', 'Product'),
  ('FACT-0007', 'GEN-MP', 'ICU', 'ΜΕΘ / ΜΑΦ', 'Καλύπτεται', 'Καλύπτονται έξοδα ΜΕΘ και ΜΑΦ ανεξάρτητα από τη θέση νοσηλείας.', 'Πίνακας Παροχών', 'Πίνακας Παροχών', NULL, NULL, NULL, 'Όροι Medical Prime.pdf', 'Νοσηλεία', 'Υψηλή', 'Product'),
  ('FACT-0008', 'GEN-MP', 'Hospitalization', 'Αποκλειστική νοσηλευτική φροντίδα', 'Καλύπτεται', 'Καλύπτεται κατά τη νοσηλεία με ανώτατο όριο 30 ημέρες ανά νοσηλεία και αιτιολογημένη εισήγηση θεράποντα ιατρού.', '30 ημέρες/νοσηλεία', NULL, NULL, NULL, NULL, 'Όροι Medical Prime.pdf', 'Αποκλειστική Νοσηλευτική Φροντίδα', 'Υψηλή', 'Product'),
  ('FACT-0009', 'GEN-MP', 'Oncology', 'Χημειοθεραπεία / ακτινοβολία', 'Καλύπτεται', 'Καλύπτονται αναγνωρισμένα έξοδα πριν ή μετά από νοσηλεία λόγω ασθένειας.', 'Πίνακας Παροχών', 'Πίνακας Παροχών', NULL, NULL, NULL, 'Όροι Medical Prime.pdf', 'Χημειοθεραπεία', 'Υψηλή', 'Product'),
  ('FACT-0010', 'GEN-MP', 'Maternity', 'Φυσιολογικός τοκετός / καισαρική', 'Υπό αναμονή', 'Με χρήση ασφαλιστικού φορέα καλύπτονται αναγνωρισμένα έξοδα σε Α θέση, χωρίς αμοιβές μαιευτήρα/βοηθού/μαίας/αναισθησιολόγου. Χωρίς χρήση φορέα καταβάλλεται επίδομα τοκετού.', 'Πίνακας Παροχών', 'Τυχόν συμμετοχή', '2 συνεχόμενα ασφαλιστικά έτη', NULL, NULL, 'Όροι Medical Prime.pdf', 'Μητρότητα', 'Υψηλή', 'Product'),
  ('FACT-0011', 'GEN-MP', 'Preventive', 'Ετήσιο check-up', 'Καλύπτεται', 'Πακέτα προληπτικών ελέγχων με συμμετοχή στον Πίνακα Παροχών.', 'Σύμφωνα με πακέτο', 'Πίνακας Παροχών', '6 μήνες', NULL, 'Partner providers', 'Όροι Medical Prime.pdf', 'Πρόληψη', 'Υψηλή', 'Product'),
  ('FACT-0012', 'GEN-MP', 'Preventive', 'Εξειδικευμένο check-up', 'Υπό αναμονή', 'Διατίθεται σε ασφαλισμένο άνω των 18 ετών μετά από ένα ασφαλιστικό έτος.', 'Σύμφωνα με πακέτο', 'Πίνακας Παροχών', '1 ασφαλιστικό έτος', NULL, 'Partner providers', 'Όροι Medical Prime.pdf', 'Εξειδικευμένο check-up', 'Υψηλή', 'Product'),
  ('FACT-0013', 'GEN-MP', 'Diagnostics', 'Διαγνωστικές / ιατρικές πράξεις', 'Καλύπτεται', 'Σε συνεργαζόμενα σημεία. Μετά την εξάντληση του ορίου, ο ασφαλισμένος πληρώνει με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου.', 'Πίνακας Παροχών', 'Μετά το όριο: ιδία πληρωμή με 30% έκπτωση', NULL, 'Ελλάδα', 'Partner network', 'Όροι Medical Prime.pdf', 'Γιατροί & Εξετάσεις', 'Υψηλή', 'Product'),
  ('FACT-0014', 'GEN-MP', 'Physiotherapy', 'Φυσικοθεραπείες', 'Καλύπτεται', 'Με παραπεμπτικό. Μετά την εξάντληση του ορίου, ιδία πληρωμή με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου.', 'Πίνακας Παροχών', 'Μετά το όριο: 30% έκπτωση', NULL, 'Ελλάδα', 'Partner network', 'Όροι Medical Prime.pdf', 'Φυσικοθεραπείες', 'Υψηλή', 'Product'),
  ('FACT-0015', 'GEN-MP', 'Deductible', 'Μεταβολή συμμετοχής', 'Κανόνας', 'Μείωση ποσού συμμετοχής ισχύει για ασθένεια μετά από 60 ημέρες και για ατύχημα από την ημερομηνία της τροποποίησης. Αύξηση ισχύει από την ημερομηνία τροποποίησης.', NULL, NULL, '60 ημέρες για ασθένεια μετά από μείωση', NULL, NULL, 'Όροι Medical Prime.pdf', 'Άρθρο 8', 'Υψηλή', 'Product'),
  ('FACT-0016', 'GEN-MP', 'Waiting', 'Γνωστές δηλωμένες παθήσεις', 'Υπό αναμονή', 'Νοσηλεία μετά από 2 έτη, ή 5 έτη αν αφορά κακοήθεια. Γιατροί & εξετάσεις μετά από 1 μήνα.', NULL, NULL, '2 / 5 έτη, 1 μήνας outpatient', NULL, NULL, 'Όροι Medical Prime.pdf', 'Άρθρο 5', 'Υψηλή', 'Product'),
  ('FACT-0017', 'GEN-MP', 'Waiting', 'Άγνωστες ειδικές παθήσεις', 'Υπό αναμονή', 'Συγκεκριμένες παθήσεις καλύπτονται μετά από 1 ή 2 έτη. Συγγενείς και ειδικές παθήσεις μετά από 10 έτη. Καρδιολογικές συγγενείς παθήσεις δεν καλύπτονται.', NULL, NULL, '1 / 2 / 10 έτη', NULL, NULL, 'Όροι Medical Prime.pdf', 'Άρθρο 5', 'Υψηλή', 'Product'),
  ('FACT-0018', 'GEN-MP', 'Policy-specific', 'Βασική παροχή ζωής σε uploaded example', 'Παράδειγμα συμβολαίου', 'Στη συγκεκριμένη uploaded έκδοση αναγράφεται ετήσιο ασφαλισμένο κεφάλαιο 200€. Δεν αποτελεί γενική τιμή Medical Prime.', '200€', NULL, NULL, NULL, NULL, 'Όροι Medical Prime.pdf', 'Ειδικοί κανόνες', 'Υψηλή', 'Policy-specific'),
  ('FACT-0019', 'GEN-MF', 'Eligibility', 'Εξαρτώμενα παιδιά', 'Καλύπτεται', 'Άγαμα τέκνα από 30 ημερών έως 25 ετών.', '30 ημέρες-25 έτη', NULL, NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Ορισμοί', 'Υψηλή', 'Product'),
  ('FACT-0020', 'GEN-MF', 'Waiting', 'Γενική έναρξη ασθένειας', 'Υπό αναμονή', 'Η κάλυψη ασθένειας αρχίζει 30 ημέρες για Ελλάδα και 180 ημέρες για εξωτερικό.', NULL, NULL, '30 / 180 ημέρες', NULL, NULL, 'Όροι Medical Family 2.pdf', 'Έναρξη', 'Υψηλή', 'Product'),
  ('FACT-0021', 'GEN-MF', 'Hospitalization', 'Ιδιωτικό νοσοκομείο', 'Καλύπτεται', '100% των αναγνωρισμένων εξόδων μετά την αφαίρεση του επιλεγμένου ποσού συμμετοχής και μέχρι το ανώτατο όριο.', 'Πίνακας Παροχών', 'Επιλεγμένο ποσό συμμετοχής', NULL, 'Ελλάδα', 'Συνεργαζόμενο ή μη', 'Όροι Medical Family 2.pdf', 'Νοσοκομειακή περίθαλψη', 'Υψηλή', 'Product'),
  ('FACT-0022', 'GEN-MF', 'Hospitalization', 'Δημόσιο νοσοκομείο', 'Καλύπτεται', '100% των αναγνωρισμένων εξόδων χωρίς παρακράτηση ποσού συμμετοχής, μέχρι το όριο.', 'Πίνακας Παροχών', '0€ παρακράτηση συμμετοχής στο δημόσιο', NULL, 'Ελλάδα', 'Δημόσιο νοσοκομείο', 'Όροι Medical Family 2.pdf', 'Νοσοκομειακή περίθαλψη', 'Υψηλή', 'Product'),
  ('FACT-0023', 'GEN-MF', 'Deductible', 'Εφαρμογή ποσού συμμετοχής', 'Κανόνας', 'Το επιλεγμένο ποσό συμμετοχής αφαιρείται μία μόνο φορά ανά ασφαλιστικό έτος.', 'Πίνακας Παροχών', 'Μία εφαρμογή ανά ασφαλιστικό έτος', NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Άρθρο 2', 'Υψηλή', 'Product'),
  ('FACT-0024', 'GEN-MF', 'One Day', 'One Day Surgery', 'Καλύπτεται', 'Με αφαίρεση συμμετοχής. Σε Ειδικά Συνεργαζόμενο Νοσοκομείο καλύπτεται απευθείας 100% χωρίς αφαίρεση συμμετοχής. Αν δεν ενημερωθεί το Call Center: 80% κάλυψη εκτός ΗΠΑ/Καναδά και 50% σε ΗΠΑ/Καναδά.', 'Πίνακας Παροχών', '0 συμμετοχή σε ειδικά συνεργαζόμενο με προενημέρωση', NULL, 'Ελλάδα/Εξωτερικό', 'Generali network', 'Όροι Medical Family 2.pdf', 'One Day Surgery', 'Υψηλή', 'Product'),
  ('FACT-0025', 'GEN-MF', 'Abroad', 'Νοσηλεία στο εξωτερικό', 'Καλύπτεται', '100% εκτός ΗΠΑ/Καναδά και 95% σε ΗΠΑ/Καναδά, μετά την αφαίρεση συμμετοχής.', 'Πίνακας Παροχών', 'Επιλεγμένο ποσό συμμετοχής', NULL, 'Εξωτερικό', NULL, 'Όροι Medical Family 2.pdf', 'Εξωτερικό', 'Υψηλή', 'Product'),
  ('FACT-0026', 'GEN-MF', 'Hospitalization', 'Προ/μετεγχειρητικές δαπάνες', 'Καλύπτεται', 'Εξετάσεις/ιατροί 30 ημέρες πριν και εξετάσεις, φάρμακα, φυσικοθεραπείες 60 ημέρες μετά την έξοδο.', '30 ημέρες πριν / 60 ημέρες μετά', 'Πίνακας Παροχών', NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Προ/μετεγχειρητικά', 'Υψηλή', 'Product'),
  ('FACT-0027', 'GEN-MF', 'Hospitalization', 'Αποκλειστική νοσοκόμα', 'Καλύπτεται', 'Πλήρους απασχόλησης, έως 30 ημέρες ανά νοσηλεία, με αιτιολογημένη εισήγηση.', '30 ημέρες/νοσηλεία', NULL, NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Νοσηλεία', 'Υψηλή', 'Product'),
  ('FACT-0028', 'GEN-MF', 'Oncology', 'Χημειοθεραπεία / ακτινοβολία / αιμοκάθαρση', 'Καλύπτεται', 'Κάλυψη για 48 μήνες από την πρώτη έξοδο για το περιστατικό. Η συμμετοχή εφαρμόζεται μία φορά στο 48μηνο και επαναλαμβάνεται μετά τη λήξη του.', '48 μήνες', 'Μία εφαρμογή συμμετοχής ανά 48μηνο', NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Oncology', 'Υψηλή', 'Product'),
  ('FACT-0029', 'GEN-MF', 'Maternity', 'Τοκετός / επιπλοκή εγκυμοσύνης', 'Υπό αναμονή', 'Επίδομα τοκετού και κάλυψη επιπλοκής εγκυμοσύνης μετά από 2 συνεχή ασφαλιστικά έτη.', 'Πίνακας Παροχών', NULL, '2 έτη', NULL, NULL, 'Όροι Medical Family 2.pdf', 'Μητρότητα', 'Υψηλή', 'Product'),
  ('FACT-0030', 'GEN-MF', 'Cash benefits', 'Επίδομα νοσηλείας και ΜΕΘ', 'Καλύπτεται', 'Έως 30 ημέρες ανά νοσηλεία για ημερήσιο επίδομα νοσηλείας και έως 30 ημέρες για επίδομα ΜΕΘ.', '30 ημέρες έκαστο', 'Ποσά στον Πίνακα Παροχών', NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Επιδόματα', 'Υψηλή', 'Product'),
  ('FACT-0031', 'GEN-MF', 'Waiting', 'Συγγενείς παθήσεις', 'Υπό αναμονή', 'Μετά από 2 έτη· για ασφαλισμένα τέκνα απαιτείται επίσης συμπλήρωση 5ου έτους ηλικίας. Άλλες ειδικές συγγενείς/παθήσεις μετά από 10 έτη.', NULL, NULL, '2 έτη + ηλικία 5 / 10 έτη', NULL, NULL, 'Όροι Medical Family 2.pdf', 'Αναμονές', 'Υψηλή', 'Product'),
  ('FACT-0032', 'GEN-MF', 'Deductible', 'Μελλοντική μείωση συμμετοχής χωρίς νέο underwriting', 'Προαιρετικός κανόνας', 'Μία φορά έως το 60ό έτος, σε επέτειο, αν είχε προεπιλεγεί. Επιβάρυνση 5% για μία κλίμακα ή 10% για δύο κλίμακες και απαιτούνται 5 συνεχόμενα έτη εξόφλησης.', NULL, '5% ή 10% επιβάρυνση ασφαλίστρου', '5 συνεχόμενα έτη', NULL, NULL, 'Όροι Medical Family 2.pdf', 'Ειδικοί κανόνες', 'Υψηλή', 'Product'),
  ('FACT-0033', 'GEN-MF', 'Deductible', 'Μείωση συμμετοχής με underwriting', 'Κανόνας', 'Μπορεί να ζητηθεί σε επέτειο με έλεγχο ασφαλισιμότητας. Η μειωμένη συμμετοχή για ασθένεια ισχύει μετά από 60 ημέρες.', NULL, NULL, '60 ημέρες για ασθένεια', NULL, NULL, 'Όροι Medical Family 2.pdf', 'Άρθρο 8', 'Υψηλή', 'Product'),
  ('FACT-0034', 'GEN-MF', 'Bonus', 'Επίδομα καλής χρήσης', 'Υπό όρους', '50% της αποζημίωσης που κατέβαλε άλλος φορέας, μετά την αφαίρεση συμμετοχής και μόνο αν η αποζημίωση του άλλου φορέα υπερβαίνει τη συμμετοχή.', 'Όριο στον Πίνακα Παροχών', '50%', NULL, NULL, NULL, 'Όροι Medical Family 2.pdf', 'Bonus καλής χρήσης', 'Υψηλή', 'Product'),
  ('FACT-0035', 'INT-MS', 'Hospitalization', 'Νοσηλεία στην Ελλάδα', 'Καλύπτεται', 'Κάλυψη σε οποιοδήποτε ιδιωτικό ή δημόσιο νοσοκομείο στην Ελλάδα. Σε συνεργαζόμενο νοσοκομείο η εταιρία καταβάλλει απευθείας τα καλυπτόμενα έξοδα.', 'Πίνακας Καλύψεων', 'Πίνακας Καλύψεων', NULL, 'Ελλάδα', 'MEDISYSTEM network', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 17', 'Υψηλή', 'Product'),
  ('FACT-0036', 'INT-MS', 'Process', 'Παραπεμπτικό δικτύου', 'Κρίσιμος κανόνας', 'Η κάλυψη και η προσωπική επιβάρυνση διαφοροποιούνται ανάλογα με παραπεμπτικό από γιατρό του Δικτύου MEDISYSTEM.', NULL, NULL, NULL, 'Ελλάδα', 'MEDISYSTEM network', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 17', 'Υψηλή', 'Product'),
  ('FACT-0037', 'INT-MS', 'Surgery', 'Αμοιβές χειρουργών', 'Καλύπτεται', 'Πίνακες ανά ειδικότητα και βαρύτητα: από 100€ έως 4.550€. Αμοιβές αναισθησιολόγου από 60€ έως 850€. Κάθε επιπλέον επέμβαση καλύπτεται κατά 20%.', '100€-4.550€', 'Αναισθησιολόγος 60€-850€', NULL, NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Πίνακες αμοιβών', 'Υψηλή', 'Product'),
  ('FACT-0038', 'INT-MS', 'Oncology', 'Χημειοθεραπεία', 'Καλύπτεται', 'Εάν άλλος φορέας καλύψει μέρος της χημειοθεραπείας, η εταιρία καλύπτει το 100% της διαφοράς μέχρι το όριο.', 'Πίνακας Καλύψεων', '100% διαφοράς', NULL, NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Νοσηλεία', 'Υψηλή', 'Product'),
  ('FACT-0039', 'INT-MS', 'Waiting', 'Καρκίνος / στεφανιαία / νοσηλεία εκτός Ευρώπης', 'Υπό αναμονή', 'Καλύπτονται μετά από 6 μήνες. Κάθε άλλη ασθένεια που δεν έχει ειδική αναμονή και εκδηλώνεται στον πρώτο μήνα δεν καλύπτεται.', NULL, NULL, '6 μήνες / 1 μήνας general', NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή', 'Product'),
  ('FACT-0040', 'INT-MS', 'Waiting', 'Ομάδα παθήσεων 1 ασφαλιστικής περιόδου', 'Υπό αναμονή', 'Αμυγδαλές, κρεατάκια, κύστη κόκκυγος, κιρσοί, γόνατο (εκτός καταγμάτων), κήλες, αιμορροΐδες/ραγάδες/συρίγγιο, καταρράκτης, γλαύκωμα, ινομυώματα, κύστεις ωοθηκών, ενδομητρίωση, χολή, λιθίαση νεφρών, ρινικό διάφραγμα/παραρρίνια, καλοήθεις παθήσεις δέρματος/μαστού/θυρεοειδούς/παραθυρεοειδούς.', NULL, NULL, '1 ασφαλιστική περίοδος', NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή', 'Product'),
  ('FACT-0041', 'INT-MS', 'Waiting', 'Ομάδα παθήσεων 2 ασφαλιστικών περιόδων', 'Υπό αναμονή', 'Εκκολπώματα, επιπλοκές διαβήτη σε αμφιβληστροειδή/αγγεία/νεφρά, ιατρικώς επιβεβλημένη διακοπή κύησης για χρωμοσωμιακές/ανατομικές ανωμαλίες, κίρρωση ήπατος, μεταμόσχευση κερατοειδούς, ανδρικά γεννητικά όργανα, ορθοκήλη/κυστεοκήλη/ακράτεια, ανεύρυσμα αορτής/περιφερική αγγειοπάθεια, συγκεκριμένες συγγενείς παθήσεις και καλοήθεις όγκοι/κύστεις, στραβισμός, προληπτική μαστεκτομή υπό προϋποθέσεις.', NULL, NULL, '2 ασφαλιστικές περίοδοι', NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή', 'Product'),
  ('FACT-0042', 'INT-MS', 'Waiting', 'Παχυσαρκία / διαφραγματοκήλη', 'Υπό αναμονή', 'Χειρουργική νοσογόνου παχυσαρκίας με BMI>40 και χειρουργική διαφραγματοκήλης καλύπτονται μετά από 5 ασφαλιστικές περιόδους.', NULL, NULL, '5 ασφαλιστικές περίοδοι', NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή', 'Product'),
  ('FACT-0043', 'INT-MS', 'Waiting', 'Βαλβίδες / συγγενείς νευρικού-μυοσκελετικού-καρδιαγγειακού / μεταμοσχεύσεις', 'Υπό αναμονή', 'Καλύπτονται μετά από 10 συνεχόμενες ασφαλιστικές περιόδους.', NULL, NULL, '10 ασφαλιστικές περίοδοι', NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή', 'Product'),
  ('FACT-0044', 'INT-MS', 'Assistance', 'Άμεση Ιατρική Βοήθεια', 'Καλύπτεται', 'Ο ασφαλισμένος εντάσσεται στην υπηρεσία βοήθειας με τους ειδικούς όρους του προγράμματος.', NULL, NULL, NULL, 'Ελλάδα/ταξίδι', NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άμεση Ιατρική Βοήθεια', 'Υψηλή', 'Product'),
  ('FACT-0045', 'INT-MS', 'Renewal', 'Ανανέωση', 'Κανόνας', 'Ετήσια ανανέωση χωρίς νέο έλεγχο ασφαλισιμότητας, εφόσον καταβληθεί το νέο ασφάλιστρο σύμφωνα με τους όρους.', '1 έτος', NULL, NULL, NULL, NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Ανανέωση', 'Υψηλή', 'Product'),
  ('FACT-0046', 'INT-BW-HOSP', 'Hospitalization', 'Νοσηλεία από ασθένεια ή ατύχημα', 'Καλύπτεται', 'Πλάνα Α, Β, Γ. Μέγιστη συνεχής νοσηλεία 365 ημέρες. Έναρξη 30 ημέρες για Ελλάδα και 180 ημέρες για εξωτερικό.', '365 ημέρες', 'Πίνακας Καλύψεων', '30 / 180 ημέρες', 'Ελλάδα/Εξωτερικό', 'INTERAMERICAN network', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή', 'Product'),
  ('FACT-0047', 'INT-BW-HOSP', 'Surgery', 'Αμοιβές χειρουργών', 'Καλύπτεται', 'Ανά ειδικότητα και βαρύτητα: 100€ έως 4.550€. Αμοιβές αναισθησιολόγων 60€ έως 850€. Κάθε πρόσθετη επέμβαση αναγνωρίζεται κατά 20%.', '100€-4.550€', '60€-850€ αναισθησιολόγος', NULL, NULL, NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Πίνακες αμοιβών', 'Υψηλή', 'Product'),
  ('FACT-0048', 'INT-BW-HOSP', 'One Day', 'Χειρουργική μιας ημέρας', 'Καλύπτεται', 'Περιλαμβάνεται νοσηλεία χωρίς διανυκτέρευση για χειρουργική επέμβαση μίας ημέρας.', 'Πίνακας Καλύψεων', 'Πίνακας Καλύψεων', NULL, NULL, NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή', 'Product'),
  ('FACT-0049', 'INT-BW-HOSP', 'ICU', 'ΜΕΘ', 'Καλύπτεται', 'Καλύπτεται στο πλαίσιο νοσηλείας σύμφωνα με το πλάνο και τον Πίνακα Καλύψεων.', 'Πίνακας Καλύψεων', 'Πίνακας Καλύψεων', NULL, NULL, NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή', 'Product'),
  ('FACT-0050', 'INT-BW-HOSP', 'Surgery', 'Αμοιβές χειρουργικής μιας ημέρας', 'Καλύπτεται', 'Πολύ μικρή 110€, μικρή 200€, μεσαία 410€, μεγάλη 580€, βαρεία 800€, εξαιρετικά βαρεία 1.000€, ειδική 1.400€.', '110€-1.400€', NULL, NULL, NULL, NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'One Day fee table', 'Υψηλή', 'Product'),
