INSERT INTO catalog.deductible_rule (deductible_id, product_id, coverage_case, exact_rule, practical_meaning, period_frequency, source_filename, article_section, confidence) VALUES
  ('DED-0001', 'GEN-MP', 'Νοσηλεία στην Ελλάδα', 'Πίνακας Παροχών', '100% των αναγνωρισμένων εξόδων μόνο σε Συνεργαζόμενο Νοσοκομείο, μέχρι το όριο και μετά την τυχόν συμμετοχή.', NULL, 'Όροι Medical Prime.pdf', 'Άρθρο 4', 'Υψηλή'),
  ('DED-0002', 'GEN-MP', 'Νοσηλεία στο εξωτερικό', 'Πίνακας Παροχών', '100% εκτός ΗΠΑ/Καναδά και 90% σε ΗΠΑ/Καναδά, με χρήση ασφαλιστικού φορέα και τις προβλεπόμενες θεωρήσεις/μεταφράσεις.', NULL, 'Όροι Medical Prime.pdf', 'Νοσηλεία στο Εξωτερικό', 'Υψηλή'),
  ('DED-0003', 'GEN-MP', 'One Day Surgery & One Day Clinic', 'Ποσοστό + ανώτατο ποσό στον Πίνακα Παροχών', 'Μόνο σε Συνεργαζόμενο Νοσοκομείο. Απευθείας κάλυψη έως το όριο. Ο ασφαλισμένος πληρώνει το ποσοστό συμμετοχής, με ανώτατο όριο το ποσό της συμμετοχής του.', NULL, 'Όροι Medical Prime.pdf', 'One Day', 'Υψηλή'),
  ('DED-0004', 'GEN-MP', 'Έκτακτα / επείγοντα', 'Συμμετοχή στον Πίνακα Παροχών', 'Πρώτες βοήθειες στα εξωτερικά ιατρεία Συνεργαζόμενου Νοσοκομείου λόγω ασθένειας ή ατυχήματος.', NULL, 'Όροι Medical Prime.pdf', 'Emergency', 'Υψηλή'),
  ('DED-0005', 'GEN-MP', 'ΜΕΘ / ΜΑΦ', 'Πίνακας Παροχών', 'Καλύπτονται έξοδα ΜΕΘ και ΜΑΦ ανεξάρτητα από τη θέση νοσηλείας.', NULL, 'Όροι Medical Prime.pdf', 'Νοσηλεία', 'Υψηλή'),
  ('DED-0006', 'GEN-MP', 'Χημειοθεραπεία / ακτινοβολία', 'Πίνακας Παροχών', 'Καλύπτονται αναγνωρισμένα έξοδα πριν ή μετά από νοσηλεία λόγω ασθένειας.', NULL, 'Όροι Medical Prime.pdf', 'Χημειοθεραπεία', 'Υψηλή'),
  ('DED-0007', 'GEN-MP', 'Φυσιολογικός τοκετός / καισαρική', 'Τυχόν συμμετοχή', 'Με χρήση ασφαλιστικού φορέα καλύπτονται αναγνωρισμένα έξοδα σε Α θέση, χωρίς αμοιβές μαιευτήρα/βοηθού/μαίας/αναισθησιολόγου. Χωρίς χρήση φορέα καταβάλλεται επίδομα τοκετού.', '2 συνεχόμενα ασφαλιστικά έτη', 'Όροι Medical Prime.pdf', 'Μητρότητα', 'Υψηλή'),
  ('DED-0008', 'GEN-MP', 'Ετήσιο check-up', 'Πίνακας Παροχών', 'Πακέτα προληπτικών ελέγχων με συμμετοχή στον Πίνακα Παροχών.', '6 μήνες', 'Όροι Medical Prime.pdf', 'Πρόληψη', 'Υψηλή'),
  ('DED-0009', 'GEN-MP', 'Εξειδικευμένο check-up', 'Πίνακας Παροχών', 'Διατίθεται σε ασφαλισμένο άνω των 18 ετών μετά από ένα ασφαλιστικό έτος.', '1 ασφαλιστικό έτος', 'Όροι Medical Prime.pdf', 'Εξειδικευμένο check-up', 'Υψηλή'),
  ('DED-0010', 'GEN-MP', 'Διαγνωστικές / ιατρικές πράξεις', 'Μετά το όριο: ιδία πληρωμή με 30% έκπτωση', 'Σε συνεργαζόμενα σημεία. Μετά την εξάντληση του ορίου, ο ασφαλισμένος πληρώνει με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου.', NULL, 'Όροι Medical Prime.pdf', 'Γιατροί & Εξετάσεις', 'Υψηλή'),
  ('DED-0011', 'GEN-MP', 'Φυσικοθεραπείες', 'Μετά το όριο: 30% έκπτωση', 'Με παραπεμπτικό. Μετά την εξάντληση του ορίου, ιδία πληρωμή με έκπτωση 30% επί ιδιωτικού τιμοκαταλόγου.', NULL, 'Όροι Medical Prime.pdf', 'Φυσικοθεραπείες', 'Υψηλή'),
  ('DED-0012', 'GEN-MP', 'Μεταβολή συμμετοχής', 'Μείωση ποσού συμμετοχής ισχύει για ασθένεια μετά από 60 ημέρες και για ατύχημα από την ημερομηνία της τροποποίησης. Αύξηση ισχύει από την ημερομηνία τροποποίησης.', 'Μείωση ποσού συμμετοχής ισχύει για ασθένεια μετά από 60 ημέρες και για ατύχημα από την ημερομηνία της τροποποίησης. Αύξηση ισχύει από την ημερομηνία τροποποίησης.', '60 ημέρες για ασθένεια μετά από μείωση', 'Όροι Medical Prime.pdf', 'Άρθρο 8', 'Υψηλή'),
  ('DED-0013', 'GEN-MF', 'Ιδιωτικό νοσοκομείο', 'Επιλεγμένο ποσό συμμετοχής', '100% των αναγνωρισμένων εξόδων μετά την αφαίρεση του επιλεγμένου ποσού συμμετοχής και μέχρι το ανώτατο όριο.', NULL, 'Όροι Medical Family 2.pdf', 'Νοσοκομειακή περίθαλψη', 'Υψηλή'),
  ('DED-0014', 'GEN-MF', 'Δημόσιο νοσοκομείο', '0€ παρακράτηση συμμετοχής στο δημόσιο', '100% των αναγνωρισμένων εξόδων χωρίς παρακράτηση ποσού συμμετοχής, μέχρι το όριο.', NULL, 'Όροι Medical Family 2.pdf', 'Νοσοκομειακή περίθαλψη', 'Υψηλή'),
  ('DED-0015', 'GEN-MF', 'Εφαρμογή ποσού συμμετοχής', 'Μία εφαρμογή ανά ασφαλιστικό έτος', 'Το επιλεγμένο ποσό συμμετοχής αφαιρείται μία μόνο φορά ανά ασφαλιστικό έτος.', NULL, 'Όροι Medical Family 2.pdf', 'Άρθρο 2', 'Υψηλή'),
  ('DED-0016', 'GEN-MF', 'One Day Surgery', '0 συμμετοχή σε ειδικά συνεργαζόμενο με προενημέρωση', 'Με αφαίρεση συμμετοχής. Σε Ειδικά Συνεργαζόμενο Νοσοκομείο καλύπτεται απευθείας 100% χωρίς αφαίρεση συμμετοχής. Αν δεν ενημερωθεί το Call Center: 80% κάλυψη εκτός ΗΠΑ/Καναδά και 50% σε ΗΠΑ/Καναδά.', NULL, 'Όροι Medical Family 2.pdf', 'One Day Surgery', 'Υψηλή'),
  ('DED-0017', 'GEN-MF', 'Νοσηλεία στο εξωτερικό', 'Επιλεγμένο ποσό συμμετοχής', '100% εκτός ΗΠΑ/Καναδά και 95% σε ΗΠΑ/Καναδά, μετά την αφαίρεση συμμετοχής.', NULL, 'Όροι Medical Family 2.pdf', 'Εξωτερικό', 'Υψηλή'),
  ('DED-0018', 'GEN-MF', 'Προ/μετεγχειρητικές δαπάνες', 'Πίνακας Παροχών', 'Εξετάσεις/ιατροί 30 ημέρες πριν και εξετάσεις, φάρμακα, φυσικοθεραπείες 60 ημέρες μετά την έξοδο.', NULL, 'Όροι Medical Family 2.pdf', 'Προ/μετεγχειρητικά', 'Υψηλή'),
  ('DED-0019', 'GEN-MF', 'Χημειοθεραπεία / ακτινοβολία / αιμοκάθαρση', 'Μία εφαρμογή συμμετοχής ανά 48μηνο', 'Κάλυψη για 48 μήνες από την πρώτη έξοδο για το περιστατικό. Η συμμετοχή εφαρμόζεται μία φορά στο 48μηνο και επαναλαμβάνεται μετά τη λήξη του.', NULL, 'Όροι Medical Family 2.pdf', 'Oncology', 'Υψηλή'),
  ('DED-0020', 'GEN-MF', 'Επίδομα νοσηλείας και ΜΕΘ', 'Ποσά στον Πίνακα Παροχών', 'Έως 30 ημέρες ανά νοσηλεία για ημερήσιο επίδομα νοσηλείας και έως 30 ημέρες για επίδομα ΜΕΘ.', NULL, 'Όροι Medical Family 2.pdf', 'Επιδόματα', 'Υψηλή'),
  ('DED-0021', 'GEN-MF', 'Μελλοντική μείωση συμμετοχής χωρίς νέο underwriting', '5% ή 10% επιβάρυνση ασφαλίστρου', 'Μία φορά έως το 60ό έτος, σε επέτειο, αν είχε προεπιλεγεί. Επιβάρυνση 5% για μία κλίμακα ή 10% για δύο κλίμακες και απαιτούνται 5 συνεχόμενα έτη εξόφλησης.', '5 συνεχόμενα έτη', 'Όροι Medical Family 2.pdf', 'Ειδικοί κανόνες', 'Υψηλή'),
  ('DED-0022', 'GEN-MF', 'Μείωση συμμετοχής με underwriting', 'Μπορεί να ζητηθεί σε επέτειο με έλεγχο ασφαλισιμότητας. Η μειωμένη συμμετοχή για ασθένεια ισχύει μετά από 60 ημέρες.', 'Μπορεί να ζητηθεί σε επέτειο με έλεγχο ασφαλισιμότητας. Η μειωμένη συμμετοχή για ασθένεια ισχύει μετά από 60 ημέρες.', '60 ημέρες για ασθένεια', 'Όροι Medical Family 2.pdf', 'Άρθρο 8', 'Υψηλή'),
  ('DED-0023', 'GEN-MF', 'Επίδομα καλής χρήσης', '50%', '50% της αποζημίωσης που κατέβαλε άλλος φορέας, μετά την αφαίρεση συμμετοχής και μόνο αν η αποζημίωση του άλλου φορέα υπερβαίνει τη συμμετοχή.', NULL, 'Όροι Medical Family 2.pdf', 'Bonus καλής χρήσης', 'Υψηλή'),
  ('DED-0024', 'INT-MS', 'Νοσηλεία στην Ελλάδα', 'Πίνακας Καλύψεων', 'Κάλυψη σε οποιοδήποτε ιδιωτικό ή δημόσιο νοσοκομείο στην Ελλάδα. Σε συνεργαζόμενο νοσοκομείο η εταιρία καταβάλλει απευθείας τα καλυπτόμενα έξοδα.', NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 17', 'Υψηλή'),
  ('DED-0025', 'INT-MS', 'Αμοιβές χειρουργών', 'Αναισθησιολόγος 60€-850€', 'Πίνακες ανά ειδικότητα και βαρύτητα: από 100€ έως 4.550€. Αμοιβές αναισθησιολόγου από 60€ έως 850€. Κάθε επιπλέον επέμβαση καλύπτεται κατά 20%.', NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Πίνακες αμοιβών', 'Υψηλή'),
  ('DED-0026', 'INT-MS', 'Χημειοθεραπεία', '100% διαφοράς', 'Εάν άλλος φορέας καλύψει μέρος της χημειοθεραπείας, η εταιρία καλύπτει το 100% της διαφοράς μέχρι το όριο.', NULL, 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Νοσηλεία', 'Υψηλή'),
  ('DED-0027', 'INT-BW-HOSP', 'Νοσηλεία από ασθένεια ή ατύχημα', 'Πίνακας Καλύψεων', 'Πλάνα Α, Β, Γ. Μέγιστη συνεχής νοσηλεία 365 ημέρες. Έναρξη 30 ημέρες για Ελλάδα και 180 ημέρες για εξωτερικό.', '30 / 180 ημέρες', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή'),
  ('DED-0028', 'INT-BW-HOSP', 'Αμοιβές χειρουργών', '60€-850€ αναισθησιολόγος', 'Ανά ειδικότητα και βαρύτητα: 100€ έως 4.550€. Αμοιβές αναισθησιολόγων 60€ έως 850€. Κάθε πρόσθετη επέμβαση αναγνωρίζεται κατά 20%.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Πίνακες αμοιβών', 'Υψηλή'),
  ('DED-0029', 'INT-BW-HOSP', 'Χειρουργική μιας ημέρας', 'Πίνακας Καλύψεων', 'Περιλαμβάνεται νοσηλεία χωρίς διανυκτέρευση για χειρουργική επέμβαση μίας ημέρας.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή'),
  ('DED-0030', 'INT-BW-HOSP', 'ΜΕΘ', 'Πίνακας Καλύψεων', 'Καλύπτεται στο πλαίσιο νοσηλείας σύμφωνα με το πλάνο και τον Πίνακα Καλύψεων.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή'),
  ('DED-0031', 'INT-BW-ACC', 'Νοσηλεία μόνο λόγω ατυχήματος', 'Πίνακας Καλύψεων', 'Καλύπτει νοσηλεία, ΤΕΠ/βραχεία νοσηλεία και ΜΕΘ μόνο όταν η αιτία είναι ατύχημα.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Accident', 'Υψηλή'),
  ('DED-0032', 'INT-BW-ACC', 'Αμοιβές χειρουργών και One Day', '60€-850€', 'Ίδιοι πίνακες ανώτατων αμοιβών: χειρουργοί έως 4.550€, αναισθησιολόγοι έως 850€, One Day έως 1.400€.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Accident', 'Υψηλή'),
  ('DED-0033', 'INT-BW-ER', 'Επείγον περιστατικό', 'Πίνακας Καλύψεων', 'Ιατρικές επισκέψεις, διαγνωστικές εξετάσεις και συναφή αναγνωριζόμενα έξοδα σε ΤΕΠ/Μονάδα Βραχείας Νοσηλείας σύμφωνα με τον Πίνακα Καλύψεων.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Emergency', 'Υψηλή'),
  ('DED-0034', 'INT-BW-OP', 'Γιατροί & διαγνωστικές', 'Πίνακας Καλύψεων', 'Ιατρικές επισκέψεις και διαγνωστικές μέσω MEDIFIRST, Αθηναϊκής Mediclinic και Δικτύου Υγείας. Εκτός δικτύου χρήση μόνο όταν οι όροι το επιτρέπουν.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Doctors & Diagnostics', 'Υψηλή'),
  ('DED-0035', 'INT-BW-MEDS', 'Φάρμακα', 'Πίνακας Καλύψεων', 'Κάλυψη φαρμακευτικών δαπανών σύμφωνα με το όριο και τη συμμετοχή του Πίνακα Καλύψεων.', NULL, 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Medicines', 'Υψηλή'),
  ('DED-0036', 'GRO-SPR', 'Διαγνωστικές εξετάσεις', '0% υπό 4 προϋποθέσεις ή 15%', 'Έως 1.500€ ετησίως. Μηδενική συμμετοχή μόνο όταν χρησιμοποιείται ασφαλιστικός φορέας, οι εξετάσεις είναι στο ΦΕΚ, υπάρχει διαθέσιμο plafond και ο πάροχος είναι συμβεβλημένος με ΕΟΠΥΥ. Διαφορετικά συμμετοχή 15%.', '1 μήνας', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('DED-0037', 'GRO-SPR', 'Ιατρικές επισκέψεις ενηλίκων', '10€/επίσκεψη', 'Απεριόριστες επισκέψεις σε συνεργαζόμενους ιατρούς ενηλίκων.', '1 μήνας', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('DED-0038', 'GRO-SPR', 'Παιδίατρος / παιδοχειρουργός', '10€/επίσκεψη', 'Απεριόριστες επισκέψεις στο πανελλαδικό δίκτυο.', '1 μήνας', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('DED-0039', 'GRO-SPR', 'Λοιπές παιδοειδικότητες', '30€ / 50€ / 100€', 'Επιμελητές 30€, Διευθυντές 50€, Αναπτυξιολόγος 100€.', '1 μήνας', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('DED-0040', 'GRO-SPR', 'Φυσικοθεραπείες', '20€/συνεδρία', 'Απεριόριστες συνεδρίες σε συνεργαζόμενους φυσιοθεραπευτές.', '1 μήνας', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('DED-0041', 'GRO-SPR', 'Ετήσιο check-up', '0€ στον πίνακα', 'Μία φορά ετησίως, χωρίς αναγραφόμενη συμμετοχή στον πίνακα.', '1 μήνας', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('DED-0042', 'GRO-SPR', 'Επείγοντα Ευρωκλινικής', '0€ / 50€ και έκπτωση 30%', 'Δωρεάν επίσκεψη σε εφημερεύοντα ιατρό, 50€ για μη εφημερεύουσα ειδικότητα, διαγνωστικές έως 200€ ανά περιστατικό και 30% έκπτωση σε ιατρικές πράξεις.', '1 μήνας', 'Sante-Principe-june2026.pdf', 'Emergency benefits', 'Υψηλή'),
  ('DED-0043', 'GRO-SPR', 'Διάρκεια και ανανέωση', '1,20% / 2,25% επιβάρυνση', 'Ετήσια διάρκεια. Η εταιρία μπορεί σε ανανέωση να τροποποιήσει όρους, παροχές και ύψη για το σύνολο ασφαλισμένων. Εξάμηνη πληρωμή έχει αρχική επιβάρυνση 1,20% και τρίμηνη 2,25%.', NULL, 'oroi-sante-Principe-june2026.pdf', 'Ανανέωση/πληρωμή', 'Υψηλή'),
  ('DED-0044', 'GRO-SPA', 'Διαγνωστικές', '0% εντός ορίου / 40% έκπτωση μετά', '100% κάλυψη σε δίκτυο Βιοϊατρικής με παραπεμπτικό. Μετά την υπέρβαση παρέχεται 40% έκπτωση.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0045', 'GRO-SPA', 'Ιατρικές επισκέψεις στο ιατρείο', '10€/επίσκεψη', 'Έως 5 επισκέψεις ετησίως.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0046', 'GRO-SPA', 'Ιατρός στο σπίτι', '20€ / πρόσθετη υπηρεσία 60€-80€', '2 επισκέψεις ετησίως με συμμετοχή 20€. Πρόσθετη υπηρεσία επείγοντος: 60€ εργάσιμες ή 80€ μη εργάσιμες σύμφωνα με το υλικό 2019.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0047', 'GRO-SPA', 'Φυσικοθεραπείες', '20€/συνεδρία', 'Απεριόριστες συνεδρίες.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0048', 'GRO-SPA', 'Check-up ενηλίκου', '0€', 'Ετήσιο check-up χωρίς χρέωση.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Check-up', 'Υψηλή'),
  ('DED-0049', 'GRO-SPA', 'Προγεννητικός έλεγχος', '0€', 'Δωρεάν μία φορά ετησίως.', '12 μήνες', 'IPIDsante-Primaire-ενηλικων-(Φ14)-20230703.pdf', 'IPID', 'Υψηλή'),
  ('DED-0050', 'GRO-SPC', 'Διαγνωστικές παιδιού', '0% εντός ορίου / 40% έκπτωση μετά', '100% κάλυψη σε δίκτυο Βιοϊατρικής. Μετά την υπέρβαση παρέχεται 40% έκπτωση.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0051', 'GRO-SPC', 'Ιατρικές επισκέψεις παιδιού', '10€/επίσκεψη', 'Έως 5 επισκέψεις ετησίως.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0052', 'GRO-SPC', 'Οδοντιατρικός έλεγχος/καθαρισμός/φθορίωση', '0€', 'Μία φορά ετησίως χωρίς χρέωση.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('DED-0053', 'GRO-SPC', 'Check-up παιδιού', '0€', 'Ετήσιο παιδικό check-up χωρίς χρέωση.', '1 μήνας', 'Sante-Primaire-2019.pdf', 'Check-up', 'Υψηλή'),
  ('DED-0054', 'GRO-SV58A', 'Διαγνωστικές', 'Μετά το όριο: 50% έκπτωση', 'Σε συμβεβλημένο διαγνωστικό κέντρο, με χρέωση στο ετήσιο όριο και 50% έκπτωση μετά την εξάντλησή του.', '30 ημέρες για ασθένεια', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0055', 'GRO-SV58A', 'Ιατρός σε Πολυϊατρείο', '10€/επίσκεψη', 'Απεριόριστες επισκέψεις.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0056', 'GRO-SV58A', 'Συμβεβλημένος ιατρός', '15€/επίσκεψη', 'Απεριόριστες επισκέψεις στο ιατρείο.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0057', 'GRO-SV58A', 'Ιατρός κατ’ οίκον', '40€ εργάσιμες / 60€ αργίες', 'Απεριόριστες επισκέψεις κατ’ οίκον.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0058', 'GRO-SV58A', 'Αιμοληψία κατ’ οίκον', '8€ εργάσιμες / 12€ Σάββατο', 'Σε καθορισμένες περιοχές.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0059', 'GRO-SV58A', 'Επίσκεψη για εμβολιασμό', '10€', 'Επίσκεψη σε συμβεβλημένο ιατρό.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0060', 'GRO-SV58A', 'Φυσικοθεραπεία σε κέντρο', '20€/συνεδρία', 'Σε συνεργαζόμενο φυσιοθεραπευτήριο.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0061', 'GRO-SV58A', 'Φυσικοθεραπεία κατ’ οίκον', '30€/συνεδρία', 'Σε συνεργαζόμενο φυσιοθεραπευτή.', '30 ημέρες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('DED-0062', 'GRO-SV58A', 'Προγεννητικός έλεγχος', 'Στο όριο/όρους', 'Μία φορά ανά εγκυμοσύνη και μετά την πάροδο 10 μηνών από την έκδοση.', '10 μήνες', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Προγεννητικός', 'Υψηλή'),
  ('DED-0063', 'GRO-SV58A', 'COVID-19 PCR', '0€ υπό προϋποθέσεις', 'Με παραπομπή δικτύου για συμπτώματα. Σε θετικό αποτέλεσμα μπορούν να πραγματοποιηθούν συνολικά 3 tests χωρίς συμμετοχή, που αφαιρούνται από το ετήσιο όριο.', NULL, 'Εγκ-644-Προσθηκη-εξετασεων-στο-Sante-Vital.pdf', 'Circular 644', 'Υψηλή')
