INSERT INTO catalog.waiting_period (waiting_id, product_id, coverage_case, duration_text, application_text, source_filename, article_section, confidence) VALUES
  ('WAIT-0001', 'GEN-MP', 'Γενική έναρξη ασθένειας', '30 ημέρες Ελλάδα / 180 ημέρες εξωτερικό', 'Ασθένεια καλύπτεται 30 ημέρες μετά την έναρξη για Ελλάδα και 180 ημέρες για εξωτερικό. Ατύχημα από την 1η ημέρα.', 'Όροι Medical Prime.pdf', 'Γενικοί όροι', 'Υψηλή'),
  ('WAIT-0002', 'GEN-MP', 'Φυσιολογικός τοκετός / καισαρική', '2 συνεχόμενα ασφαλιστικά έτη', 'Με χρήση ασφαλιστικού φορέα καλύπτονται αναγνωρισμένα έξοδα σε Α θέση, χωρίς αμοιβές μαιευτήρα/βοηθού/μαίας/αναισθησιολόγου. Χωρίς χρήση φορέα καταβάλλεται επίδομα τοκετού.', 'Όροι Medical Prime.pdf', 'Μητρότητα', 'Υψηλή'),
  ('WAIT-0003', 'GEN-MP', 'Ετήσιο check-up', '6 μήνες', 'Πακέτα προληπτικών ελέγχων με συμμετοχή στον Πίνακα Παροχών.', 'Όροι Medical Prime.pdf', 'Πρόληψη', 'Υψηλή'),
  ('WAIT-0004', 'GEN-MP', 'Εξειδικευμένο check-up', '1 ασφαλιστικό έτος', 'Διατίθεται σε ασφαλισμένο άνω των 18 ετών μετά από ένα ασφαλιστικό έτος.', 'Όροι Medical Prime.pdf', 'Εξειδικευμένο check-up', 'Υψηλή'),
  ('WAIT-0005', 'GEN-MP', 'Μεταβολή συμμετοχής', '60 ημέρες για ασθένεια μετά από μείωση', 'Μείωση ποσού συμμετοχής ισχύει για ασθένεια μετά από 60 ημέρες και για ατύχημα από την ημερομηνία της τροποποίησης. Αύξηση ισχύει από την ημερομηνία τροποποίησης.', 'Όροι Medical Prime.pdf', 'Άρθρο 8', 'Υψηλή'),
  ('WAIT-0006', 'GEN-MP', 'Γνωστές δηλωμένες παθήσεις', '2 / 5 έτη, 1 μήνας outpatient', 'Νοσηλεία μετά από 2 έτη, ή 5 έτη αν αφορά κακοήθεια. Γιατροί & εξετάσεις μετά από 1 μήνα.', 'Όροι Medical Prime.pdf', 'Άρθρο 5', 'Υψηλή'),
  ('WAIT-0007', 'GEN-MP', 'Άγνωστες ειδικές παθήσεις', '1 / 2 / 10 έτη', 'Συγκεκριμένες παθήσεις καλύπτονται μετά από 1 ή 2 έτη. Συγγενείς και ειδικές παθήσεις μετά από 10 έτη. Καρδιολογικές συγγενείς παθήσεις δεν καλύπτονται.', 'Όροι Medical Prime.pdf', 'Άρθρο 5', 'Υψηλή'),
  ('WAIT-0008', 'GEN-MF', 'Γενική έναρξη ασθένειας', '30 / 180 ημέρες', 'Η κάλυψη ασθένειας αρχίζει 30 ημέρες για Ελλάδα και 180 ημέρες για εξωτερικό.', 'Όροι Medical Family 2.pdf', 'Έναρξη', 'Υψηλή'),
  ('WAIT-0009', 'GEN-MF', 'Τοκετός / επιπλοκή εγκυμοσύνης', '2 έτη', 'Επίδομα τοκετού και κάλυψη επιπλοκής εγκυμοσύνης μετά από 2 συνεχή ασφαλιστικά έτη.', 'Όροι Medical Family 2.pdf', 'Μητρότητα', 'Υψηλή'),
  ('WAIT-0010', 'GEN-MF', 'Συγγενείς παθήσεις', '2 έτη + ηλικία 5 / 10 έτη', 'Μετά από 2 έτη· για ασφαλισμένα τέκνα απαιτείται επίσης συμπλήρωση 5ου έτους ηλικίας. Άλλες ειδικές συγγενείς/παθήσεις μετά από 10 έτη.', 'Όροι Medical Family 2.pdf', 'Αναμονές', 'Υψηλή'),
  ('WAIT-0011', 'GEN-MF', 'Μελλοντική μείωση συμμετοχής χωρίς νέο underwriting', '5 συνεχόμενα έτη', 'Μία φορά έως το 60ό έτος, σε επέτειο, αν είχε προεπιλεγεί. Επιβάρυνση 5% για μία κλίμακα ή 10% για δύο κλίμακες και απαιτούνται 5 συνεχόμενα έτη εξόφλησης.', 'Όροι Medical Family 2.pdf', 'Ειδικοί κανόνες', 'Υψηλή'),
  ('WAIT-0012', 'GEN-MF', 'Μείωση συμμετοχής με underwriting', '60 ημέρες για ασθένεια', 'Μπορεί να ζητηθεί σε επέτειο με έλεγχο ασφαλισιμότητας. Η μειωμένη συμμετοχή για ασθένεια ισχύει μετά από 60 ημέρες.', 'Όροι Medical Family 2.pdf', 'Άρθρο 8', 'Υψηλή'),
  ('WAIT-0013', 'INT-MS', 'Καρκίνος / στεφανιαία / νοσηλεία εκτός Ευρώπης', '6 μήνες / 1 μήνας general', 'Καλύπτονται μετά από 6 μήνες. Κάθε άλλη ασθένεια που δεν έχει ειδική αναμονή και εκδηλώνεται στον πρώτο μήνα δεν καλύπτεται.', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή'),
  ('WAIT-0014', 'INT-MS', 'Ομάδα παθήσεων 1 ασφαλιστικής περιόδου', '1 ασφαλιστική περίοδος', 'Αμυγδαλές, κρεατάκια, κύστη κόκκυγος, κιρσοί, γόνατο (εκτός καταγμάτων), κήλες, αιμορροΐδες/ραγάδες/συρίγγιο, καταρράκτης, γλαύκωμα, ινομυώματα, κύστεις ωοθηκών, ενδομητρίωση, χολή, λιθίαση νεφρών, ρινικό διάφραγμα/παραρρίνια, καλοήθεις παθήσεις δέρματος/μαστού/θυρεοειδούς/παραθυρεοειδούς.', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή'),
  ('WAIT-0015', 'INT-MS', 'Ομάδα παθήσεων 2 ασφαλιστικών περιόδων', '2 ασφαλιστικές περίοδοι', 'Εκκολπώματα, επιπλοκές διαβήτη σε αμφιβληστροειδή/αγγεία/νεφρά, ιατρικώς επιβεβλημένη διακοπή κύησης για χρωμοσωμιακές/ανατομικές ανωμαλίες, κίρρωση ήπατος, μεταμόσχευση κερατοειδούς, ανδρικά γεννητικά όργανα, ορθοκήλη/κυστεοκήλη/ακράτεια, ανεύρυσμα αορτής/περιφερική αγγειοπάθεια, συγκεκριμένες συγγενείς παθήσεις και καλοήθεις όγκοι/κύστεις, στραβισμός, προληπτική μαστεκτομή υπό προϋποθέσεις.', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή'),
  ('WAIT-0016', 'INT-MS', 'Παχυσαρκία / διαφραγματοκήλη', '5 ασφαλιστικές περίοδοι', 'Χειρουργική νοσογόνου παχυσαρκίας με BMI>40 και χειρουργική διαφραγματοκήλης καλύπτονται μετά από 5 ασφαλιστικές περιόδους.', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή'),
  ('WAIT-0017', 'INT-MS', 'Βαλβίδες / συγγενείς νευρικού-μυοσκελετικού-καρδιαγγειακού / μεταμοσχεύσεις', '10 ασφαλιστικές περίοδοι', 'Καλύπτονται μετά από 10 συνεχόμενες ασφαλιστικές περιόδους.', 'Medisystem_Benefit_(έκδοση01.2026).pdf', 'Άρθρο 20', 'Υψηλή'),
  ('WAIT-0018', 'INT-BW-HOSP', 'Νοσηλεία από ασθένεια ή ατύχημα', '30 / 180 ημέρες', 'Πλάνα Α, Β, Γ. Μέγιστη συνεχής νοσηλεία 365 ημέρες. Έναρξη 30 ημέρες για Ελλάδα και 180 ημέρες για εξωτερικό.', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Νοσηλεία', 'Υψηλή'),
  ('WAIT-0019', 'INT-BW-CRIT', 'Επίδομα σοβαρών ασθενειών', '90 ημέρες', 'Εφάπαξ επίδομα για τις οριζόμενες σοβαρές ασθένειες. Η κάλυψη ξεκινά μετά από 90 ημέρες.', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 'Module Critical Illness', 'Υψηλή'),
  ('WAIT-0020', 'GRO-SPR', 'Διαγνωστικές εξετάσεις', '1 μήνας', 'Έως 1.500€ ετησίως. Μηδενική συμμετοχή μόνο όταν χρησιμοποιείται ασφαλιστικός φορέας, οι εξετάσεις είναι στο ΦΕΚ, υπάρχει διαθέσιμο plafond και ο πάροχος είναι συμβεβλημένος με ΕΟΠΥΥ. Διαφορετικά συμμετοχή 15%.', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('WAIT-0021', 'GRO-SPR', 'Ιατρικές επισκέψεις ενηλίκων', '1 μήνας', 'Απεριόριστες επισκέψεις σε συνεργαζόμενους ιατρούς ενηλίκων.', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('WAIT-0022', 'GRO-SPR', 'Παιδίατρος / παιδοχειρουργός', '1 μήνας', 'Απεριόριστες επισκέψεις στο πανελλαδικό δίκτυο.', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('WAIT-0023', 'GRO-SPR', 'Λοιπές παιδοειδικότητες', '1 μήνας', 'Επιμελητές 30€, Διευθυντές 50€, Αναπτυξιολόγος 100€.', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('WAIT-0024', 'GRO-SPR', 'Φυσικοθεραπείες', '1 μήνας', 'Απεριόριστες συνεδρίες σε συνεργαζόμενους φυσιοθεραπευτές.', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('WAIT-0025', 'GRO-SPR', 'Ετήσιο check-up', '1 μήνας', 'Μία φορά ετησίως, χωρίς αναγραφόμενη συμμετοχή στον πίνακα.', 'oroi-sante-Principe-june2026.pdf', 'Πίνακας παροχών', 'Υψηλή'),
  ('WAIT-0026', 'GRO-SPR', 'Επείγοντα Ευρωκλινικής', '1 μήνας', 'Δωρεάν επίσκεψη σε εφημερεύοντα ιατρό, 50€ για μη εφημερεύουσα ειδικότητα, διαγνωστικές έως 200€ ανά περιστατικό και 30% έκπτωση σε ιατρικές πράξεις.', 'Sante-Principe-june2026.pdf', 'Emergency benefits', 'Υψηλή'),
  ('WAIT-0027', 'GRO-SPA', 'Διαγνωστικές', '1 μήνας', '100% κάλυψη σε δίκτυο Βιοϊατρικής με παραπεμπτικό. Μετά την υπέρβαση παρέχεται 40% έκπτωση.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0028', 'GRO-SPA', 'Ιατρικές επισκέψεις στο ιατρείο', '1 μήνας', 'Έως 5 επισκέψεις ετησίως.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0029', 'GRO-SPA', 'Ιατρός στο σπίτι', '1 μήνας', '2 επισκέψεις ετησίως με συμμετοχή 20€. Πρόσθετη υπηρεσία επείγοντος: 60€ εργάσιμες ή 80€ μη εργάσιμες σύμφωνα με το υλικό 2019.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0030', 'GRO-SPA', 'Φυσικοθεραπείες', '1 μήνας', 'Απεριόριστες συνεδρίες.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0031', 'GRO-SPA', 'Check-up ενηλίκου', '1 μήνας', 'Ετήσιο check-up χωρίς χρέωση.', 'Sante-Primaire-2019.pdf', 'Check-up', 'Υψηλή'),
  ('WAIT-0032', 'GRO-SPA', 'Προγεννητικός έλεγχος', '12 μήνες', 'Δωρεάν μία φορά ετησίως.', 'IPIDsante-Primaire-ενηλικων-(Φ14)-20230703.pdf', 'IPID', 'Υψηλή'),
  ('WAIT-0033', 'GRO-SPC', 'Διαγνωστικές παιδιού', '1 μήνας', '100% κάλυψη σε δίκτυο Βιοϊατρικής. Μετά την υπέρβαση παρέχεται 40% έκπτωση.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0034', 'GRO-SPC', 'Ιατρικές επισκέψεις παιδιού', '1 μήνας', 'Έως 5 επισκέψεις ετησίως.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0035', 'GRO-SPC', 'Οδοντιατρικός έλεγχος/καθαρισμός/φθορίωση', '1 μήνας', 'Μία φορά ετησίως χωρίς χρέωση.', 'Sante-Primaire-2019.pdf', 'Παροχές', 'Υψηλή'),
  ('WAIT-0036', 'GRO-SPC', 'Check-up παιδιού', '1 μήνας', 'Ετήσιο παιδικό check-up χωρίς χρέωση.', 'Sante-Primaire-2019.pdf', 'Check-up', 'Υψηλή'),
  ('WAIT-0037', 'GRO-SV58A', 'Διαγνωστικές', '30 ημέρες για ασθένεια', 'Σε συμβεβλημένο διαγνωστικό κέντρο, με χρέωση στο ετήσιο όριο και 50% έκπτωση μετά την εξάντλησή του.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0038', 'GRO-SV58A', 'Ιατρός σε Πολυϊατρείο', '30 ημέρες', 'Απεριόριστες επισκέψεις.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0039', 'GRO-SV58A', 'Συμβεβλημένος ιατρός', '30 ημέρες', 'Απεριόριστες επισκέψεις στο ιατρείο.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0040', 'GRO-SV58A', 'Ιατρός κατ’ οίκον', '30 ημέρες', 'Απεριόριστες επισκέψεις κατ’ οίκον.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0041', 'GRO-SV58A', 'Αιμοληψία κατ’ οίκον', '30 ημέρες', 'Σε καθορισμένες περιοχές.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0042', 'GRO-SV58A', 'Επίσκεψη για εμβολιασμό', '30 ημέρες', 'Επίσκεψη σε συμβεβλημένο ιατρό.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0043', 'GRO-SV58A', 'Φυσικοθεραπεία σε κέντρο', '30 ημέρες', 'Σε συνεργαζόμενο φυσιοθεραπευτήριο.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0044', 'GRO-SV58A', 'Φυσικοθεραπεία κατ’ οίκον', '30 ημέρες', 'Σε συνεργαζόμενο φυσιοθεραπευτή.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Πίνακας Φ58Α', 'Υψηλή'),
  ('WAIT-0045', 'GRO-SV58A', 'Προγεννητικός έλεγχος', '10 μήνες', 'Μία φορά ανά εγκυμοσύνη και μετά την πάροδο 10 μηνών από την έκδοση.', 'Οροι-Sante-Vital-23-20-2020.pdf', 'Προγεννητικός', 'Υψηλή')
