INSERT INTO catalog.supplementary_benefit (benefit_id, product_id, benefit_name, exact_operation_conditions, waiting_text, duration_expiry, source_filename) VALUES
  ('SUP-GEN-MP-01', 'GEN-MP', 'Απαλλαγή πληρωμής ασφαλίστρου λόγω Μόνιμης Ολικής Ανικανότητας ασφαλισμένου', 'Η απαλλαγή αρχίζει μετά τη λήξη θεραπείας ή περίοδο αναμονής 6 μηνών. Άμεση σε πλήρη απώλεια όρασης δύο οφθαλμών ή χρήσης δύο άκρων.', '6 μήνες', 'Έως λήξη συμβολαίου ή ανάκτηση ικανότητας', 'Συμπληρωματικές Παροχές - Medical Prime.pdf'),
  ('SUP-GEN-MP-02', 'GEN-MP', 'Απαλλαγή πληρωμής ασφαλίστρου λόγω Μόνιμης Ολικής Ανικανότητας ασφαλισμένου - Απόλυτη', 'Παραλλαγή με απόλυτη κάλυψη σύμφωνα με τους ειδικούς όρους. Η άμεση αναγνώριση ισχύει στις συγκεκριμένες οριστικές απώλειες.', '6 μήνες εκτός ειδικών απωλειών', 'Έως λήξη των καλυπτόμενων παροχών', 'Συμπληρωματικές Παροχές - Medical Prime.pdf'),
  ('SUP-GEN-MP-03', 'GEN-MP', 'Απαλλαγή πληρωμής ασφαλίστρου λόγω θανάτου ή Μόνιμης Ολικής Ανικανότητας συμβαλλομένου', 'Καλύπτει τα ασφάλιστρα της βασικής και συμπληρωματικών παροχών όταν επέλθει ο ασφαλισμένος κίνδυνος του συμβαλλομένου.', '6 μήνες για αναγνώριση ανικανότητας', 'Σύμφωνα με ημερομηνίες λήξης στον Πίνακα Παροχών', 'Συμπληρωματικές Παροχές - Medical Prime.pdf'),
  ('SUP-GEN-MP-04', 'GEN-MP', 'Απαλλαγή πληρωμής ασφαλίστρου λόγω θανάτου ή Μόνιμης Ολικής Ανικανότητας συμβαλλομένου - Απόλυτη', 'Απόλυτη παραλλαγή της κάλυψης συμβαλλομένου.', '6 μήνες εκτός ειδικών απωλειών', 'Σύμφωνα με όρους', 'Συμπληρωματικές Παροχές - Medical Prime.pdf'),
  ('SUP-GEN-MF-01', 'GEN-MF', 'Προστασία Μελλοντικών Ασφαλίστρων λόγω Μόνιμης Ολικής Ανικανότητας ασφαλισμένου', 'Καταβάλλεται εφάπαξ το ασφαλισμένο κεφάλαιο μελλοντικών ασφαλίστρων. Για ατύχημα η ανικανότητα πρέπει να έχει επέλθει μέσα σε 6 μήνες. Λήγει το αργότερο στο 65ο έτος.', '6 μήνες για ατύχημα', 'Ασφαλισμένο κεφάλαιο στον Πίνακα Παροχών', 'Συμπληρωματικές Παροχές - Medical Family.pdf'),
  ('SUP-GEN-MF-02', 'GEN-MF', 'Προστασία Μελλοντικών Ασφαλίστρων λόγω θανάτου ή Μόνιμης Ολικής Ανικανότητας συμβαλλομένου', 'Καταβολή ασφαλισμένου κεφαλαίου στον συμβαλλόμενο/υποκατάστατο/ασφαλισμένο σύμφωνα με τους όρους.', 'Έως 360 ημέρες για ανικανότητα από ατύχημα', 'Ασφαλισμένο κεφάλαιο στον Πίνακα Παροχών', 'Συμπληρωματικές Παροχές - Medical Family.pdf')
ON CONFLICT (benefit_id) DO UPDATE SET
  product_id = EXCLUDED.product_id,
  benefit_name = EXCLUDED.benefit_name,
  exact_operation_conditions = EXCLUDED.exact_operation_conditions,
  waiting_text = EXCLUDED.waiting_text,
  duration_expiry = EXCLUDED.duration_expiry,
  source_filename = EXCLUDED.source_filename;

INSERT INTO catalog.claim_rule (claim_rule_id, product_id, claim_case, exact_process, deadline_limit) VALUES
  ('CLM-001', 'GEN-MP', 'Εξωτερικό', 'Υποβολή θεωρημένων και νόμιμα μεταφρασμένων δικαιολογητικών. Αποζημίωση στην Ελλάδα σε ευρώ με fixing της ημερομηνίας πληρωμής.', 'Δικαιολογητικά εντός 2 μηνών'),
  ('CLM-002', 'GEN-MP', 'Συνεργαζόμενο νοσοκομείο', 'Για επιπλέον δικαιολογητικά που ζητούνται ειδικά από συνεργαζόμενο νοσοκομείο, προθεσμία 3 ημερών από το αίτημα.', '3 ημέρες'),
  ('CLM-003', 'GEN-MF', 'Εξωτερικό', 'Προειδοποίηση τουλάχιστον 5 εργάσιμες ημέρες πριν την εισαγωγή.', '5 εργάσιμες ημέρες'),
  ('CLM-004', 'GEN-MF', 'Αποζημίωση', 'Καταβολή εντός 5 εργάσιμων ημερών από την παραλαβή όλων των πρωτότυπων δικαιολογητικών και αναγνώριση υποχρέωσης.', '5 εργάσιμες ημέρες'),
  ('CLM-005', 'INT-MS', 'Συνεργαζόμενο νοσοκομείο', 'Απευθείας καταβολή καλυπτόμενων εξόδων. Η διαδικασία διαφοροποιείται με/χωρίς παραπεμπτικό δικτύου.', 'Σύμφωνα με Άρθρο 17'),
  ('CLM-006', 'GRO-SPR', 'Διαγνωστικές', 'Η συμμετοχή 0% απαιτεί σωρευτικά χρήση ασφαλιστικού φορέα, εξέταση στο ΦΕΚ, διαθέσιμο plafond και πάροχο συμβεβλημένο με ΕΟΠΥΥ.', '4 σωρευτικές προϋποθέσεις'),
  ('CLM-007', 'GRO-SPA', 'Χρήση', 'Πριν από οποιαδήποτε χρήση απαιτείται επικοινωνία με το τηλεφωνικό κέντρο για πάροχο/ραντεβού.', 'Προηγούμενη επικοινωνία'),
  ('CLM-008', 'GRO-SV58A', 'Διαγνωστικές', 'Μετά την εξάντληση του ετήσιου ορίου, ο ασφαλισμένος πληρώνει απευθείας με έκπτωση 50% στον ιδιωτικό τιμοκατάλογο.', '50% έκπτωση')
ON CONFLICT (claim_rule_id) DO UPDATE SET
  product_id = EXCLUDED.product_id,
  claim_case = EXCLUDED.claim_case,
  exact_process = EXCLUDED.exact_process,
  deadline_limit = EXCLUDED.deadline_limit;

