INSERT INTO catalog.data_quality_issue (issue_id, scope_text, issue_text, cause_text, required_action, severity) VALUES
  ('DQ-001', 'Όλα', 'Τρέχουσα τιμολόγηση', 'Οι τιμές σε Groupama υλικό 2019/2020 είναι ιστορικές.', 'Νέα τιμολόγηση/API ή επίσημες προσφορές', 'Κρίσιμη'),
  ('DQ-002', 'Generali / Interamerican', 'Αριθμητική απαλλαγή/ανώτατο όριο', 'Τα γενικά βιβλία παραπέμπουν στον Πίνακα Παροχών/Καλύψεων.', 'Συλλογή όλων των product variants και πινάκων', 'Κρίσιμη'),
  ('DQ-003', 'GRO-SV75A', 'Πλήρης πίνακας παροχών', 'Δεν έχει ανεβεί ξεχωριστό βιβλίο/πίνακας Φ75Α.', 'Να ζητηθεί ο επίσημος πίνακας Φ75Α', 'Κρίσιμη'),
  ('DQ-004', 'Δίκτυα', 'Δυναμική ισχύς', 'Οι εταιρίες δηλώνουν ότι τα δίκτυα μπορεί να αλλάζουν.', 'Versioned network feed/μηνιαία επικαιροποίηση', 'Υψηλή'),
  ('DQ-005', 'Medical Prime', 'Policy-specific values', 'Η uploaded έκδοση περιλαμβάνει αριθμό συμβολαίου και κεφάλαιο 200€.', 'Να μην χρησιμοποιείται ως product default', 'Υψηλή'),
  ('DQ-006', 'Εξαιρέσεις', 'Auto extraction', 'Οι εξαιρέσεις εξήχθησαν από πλήρεις ενότητες αλλά χρειάζονται νομική επικύρωση και σωστή σύνδεση με module.', 'Human legal/product review', 'Κρίσιμη'),
  ('DQ-007', 'Επεμβάσεις', 'Parsing δύο στηλών', 'Οι διαδικασίες εξήχθησαν από σύνθετους πίνακες και απαιτείται δειγματοληπτικός έλεγχος severity.', 'Human validation', 'Υψηλή'),
  ('DQ-008', 'Santé Principe', 'Version control', 'Ιστορικές παροχές άρθρου 22 δεν πρέπει να εμφανίζονται ως current μετά 01.06.2026.', 'Use current version filter', 'Κρίσιμη'),
  ('DQ-009', 'Duplicate documents', 'Copies', 'Πολλά Santé Primaire/COVID αρχεία είναι αντίγραφα.', 'Dedup by document hash/version', 'Μεσαία')
ON CONFLICT (issue_id) DO UPDATE SET
  scope_text = EXCLUDED.scope_text,
  issue_text = EXCLUDED.issue_text,
  cause_text = EXCLUDED.cause_text,
  required_action = EXCLUDED.required_action,
  severity = EXCLUDED.severity;

INSERT INTO catalog.monetary_fact (monetary_id, product_id, legacy_product_reference, exact_excerpt, source_filename, pdf_page) VALUES
  ('MON-0001', 'GEN-MP', 'GEN-MP', 'Σε περίπτωση που ο Ασφαλισμένος εξαντλήσει το Ανώτατο Όριο Ευθύνης Κάλυψης, που αναγράφεται στον Πίνακα Παροχών και Καλύψεων, θα καταβάλει τα παραπάνω έξοδα που προκύπτουν με έκπτωση 30% στις τιμές του ιδιωτι- κού τιμοκαταλόγου του Συνεργαζόμενου Νοσοκομείου ή του Ιατρικού Διαγνωστικού Κέντρου.', 'Όροι Medical Prime.pdf', 24),
  ('MON-0002', 'GEN-MP', 'GEN-MP', 'Η Εταιρία καλύπτει τα Αναγνωρισμένα Έξοδα για Νοσηλεία, λόγω Ασθένειας ή Ατυχήματος, στην Ελλάδα με ποσοστό κάλυψης 100%. Πώς καλύπτεται ο Ασφαλισμένος', 'Όροι Medical Prime.pdf', 25),
  ('MON-0003', 'GEN-MP', 'GEN-MP', 'με τα παρακάτω ποσοστά κάλυψης: nn Εξωτερικό (εκτός ΗΠΑ & Καναδά): 100% nn ΗΠΑ και Καναδά: 90%', 'Όροι Medical Prime.pdf', 26),
  ('MON-0004', 'GEN-MP', 'GEN-MP', 'nn Εξωτερικό (εκτός ΗΠΑ & Καναδά): 100% nn ΗΠΑ και Καναδά: 90% Πώς καλύπτεται ο Ασφαλισμένος', 'Όροι Medical Prime.pdf', 26),
  ('MON-0005', 'GEN-MP', 'GEN-MP', 'Επιπλέον, για Χειρουργικές Επεμβάσεις Παχυσαρκίας ή άλλες αισθητικές επεμβάσεις, ο Ασφαλισμένος έχει έκ- πτωση 30% στις τιμές του ιδιωτικού τιμοκαταλόγου του Συνεργαζόμενου Νοσοκομείου για τα έξοδα της Νοσηλείας. Η παραπάνω έκπτωση δεν ισχύει για τις αμοιβές των πλαστικών χειρουργών.', 'Όροι Medical Prime.pdf', 28),
  ('MON-0006', 'GEN-MP', 'GEN-MP', 'Εξαμηνιαία Συχνότητα Πληρωμής δόσεις, επιβαρύνεται με ποσοστό 2% επί του ετήσιου Ασφαλίστρου Τα καθαρά Ασφάλιστρα κάθε δόσης του Ασφαλίστρου επιβαρύνονται με', 'Όροι Medical Prime.pdf', 32),
  ('MON-0007', 'GEN-MP', 'GEN-MP', 'Δικαίωμα Ασφαλιστηρίου ποσοστό 10% για Δικαιώματα Ασφαλιστηρίου Δικαίωμα Ασφαλιστηρίου πρώτης', 'Όροι Medical Prime.pdf', 32),
  ('MON-0008', 'GEN-MP', 'GEN-MP', 'Δικαίωμα Ασφαλιστηρίου πρώτης Η πρώτη δόση Ασφαλίστρου επιβαρύνεται με 34,50€ δόσης Ασφαλίστρου', 'Όροι Medical Prime.pdf', 32),
  ('MON-0009', 'GEN-MP', 'GEN-MP', 'Το Ετήσιο Ασφαλισμένο Κεφάλαιο είναι υποχρεωτικό, ισχύει για όλες τις ηλι- 200€ κίες και παραμένει αμετάβλητο κατά τη διάρκεια ισχύος της Παροχής', 'Όροι Medical Prime.pdf', 36),
  ('MON-0010', 'GEN-MF', 'GEN-MF', 'Εάν o Ασφαλισμένος επιλέξει για τη νοσηλεία του Ιδιωτικό Νοσοκομείο, Συνεργαζόμενο ή μη, η Εταιρία καταβάλλει ποσοστό 100% των αναγνωρισμένων εξόδων που αφορούν στη συγκεκριμένη νοσηλεία, αφού αφαιρέσει το ποσό συμμετοχής του Ασφαλισμένου και μέχρι το ανώτατο όριο', 'Όροι Medical Family 2.pdf', 17),
  ('MON-0011', 'GEN-MF', 'GEN-MF', 'Εάν ο Ασφαλισμένος επιλέξει για τη νοσηλεία του Δημόσιο Νοσοκομείο, η Εταιρία καταβάλλει ποσοστό 100% των αναγνωρισμένων εξόδων που αφορούν στη συγκεκριμένη νοσηλεία, χωρίς παρακράτηση του ποσού Συμμετοχής του Ασφαλισμένου, και μέχρι το ανώτατο όριο που αναγρά-', 'Όροι Medical Family 2.pdf', 17),
  ('MON-0012', 'GEN-MF', 'GEN-MF', 'Εάν ο Ασφαλισμένος επιλέξει ένα από τα Ειδικά Συνεργαζόμενα Νοσοκομεία, η Εταιρία καλύπτει απευθείας σε ποσοστό 100% τις αναγνωρισμένες δαπάνες του περιστατικού, χωρίς να αφαιρέσει τη συμμετοχή που έχει επιλέξει ο Ασφαλισμένος.', 'Όροι Medical Family 2.pdf', 18),
  ('MON-0013', 'GEN-MF', 'GEN-MF', 'τη συμμετοχή που έχει επιλέξει ο Ασφαλισμένος. Εάν ο Ασφαλισμένος δεν ενημερώσει το Generali Call Center, η Εταιρία καλύπτει ποσοστό 80% των δαπανών για χειρουργικές επεμβάσεις στην Ελλάδα και στο Εξωτερικό, εκτός ΗΠΑ και Κανα-', 'Όροι Medical Family 2.pdf', 18),
  ('MON-0014', 'GEN-MF', 'GEN-MF', 'των δαπανών για χειρουργικές επεμβάσεις στην Ελλάδα και στο Εξωτερικό, εκτός ΗΠΑ και Κανα- δά, όπου το ποσοστό κάλυψης είναι 50%. Οι ιατρικές αμοιβές για χειρουργικές επεμβάσεις καθορίζονται σύμφωνα με τα ανώτατα όρια που', 'Όροι Medical Family 2.pdf', 18),
  ('MON-0015', 'GEN-MF', 'GEN-MF', 'Η Εταιρία καλύπτει τα έξοδα Νοσηλείας στο Εξωτερικό σύμφωνα με τα ποσοστά: n Εξωτερικό (εκτός ΗΠΑ & Καναδά): 100% n ΗΠΑ & Καναδά: 95%', 'Όροι Medical Family 2.pdf', 18),
  ('MON-0016', 'GEN-MF', 'GEN-MF', 'n Εξωτερικό (εκτός ΗΠΑ & Καναδά): 100% n ΗΠΑ & Καναδά: 95% Η Εταιρία αποζημιώνει τον Ασφαλισμένο με βάση τα πιο πάνω ποσοστά αφού αφαιρέσει το ποσό', 'Όροι Medical Family 2.pdf', 18),
  ('MON-0017', 'GEN-MF', 'GEN-MF', 'Αν ο Ασφαλισμένος επιλέξει Ειδικά Συνεργαζόμενο Νοσοκομείο, η Εταιρία καλύπτει απευθείας σε ποσοστό 100% τα αναγνωριζόμενα έξοδα του έκτακτου / επείγοντος περιστατικού μέχρι το ανώτατο όριο που αναγράφεται στον Πίνακα Παροχών. Αν το σύνολο των εξόδων είναι μεγαλύ-', 'Όροι Medical Family 2.pdf', 19),
  ('MON-0018', 'GEN-MF', 'GEN-MF', 'λύπτεται από την Παροχή και έχει αποζημιωθεί από αυτή) θα καταβάλει Επίδομα (bonus) Καλής Χρήσης, που είναι ποσοστό 50% της αποζημίωσης που καταβλήθηκε στον Ασφαλισμένο από τον πρώτο ασφαλιστικό φορέα, μετά την αφαίρεση του ποσού Συμμετοχής του Ασφαλισμένου και με', 'Όροι Medical Family 2.pdf', 22),
  ('MON-0019', 'GEN-MF', 'GEN-MF', 'στην Αίτηση Ασφάλισης. Μείωση ποσού συμμετοχής • Ετήσια επιβάρυνση 5% στα ετήσια καθαρά χωρίς έλεγχο ασφαλισιμότητας ασφάλιστρα για μείωση προς την αμέσως', 'Όροι Medical Family 2.pdf', 33),
  ('MON-0020', 'GEN-MF', 'GEN-MF', 'μικρότερη κλίμακα συμμετοχής. • Ετήσια επιβάρυνση 10% στα ετήσια καθαρά ασφάλιστρα για μείωση της συμμετοχής κατά', 'Όροι Medical Family 2.pdf', 33),
  ('MON-0021', NULL, 'INT-BW', '& βοηθών χειρουργών Αγγειοχειρουργικές €100 €210 €800 €1.200 €1.650 €2.350 €3.500 Γενικής χειρουργικής €100 €210 €800 €1.200 €1.650 €2.350 €3.500', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 11),
