  ('MON-0023', NULL, 'INT-BW', 'Γενικής χειρουργικής €100 €210 €800 €1.200 €1.650 €2.350 €3.500 Γυναικολογικές €100 €210 €800 €1.200 €1.650 €2.350 €3.500 Θωρακοχειρουργικές – – €1.040 €1.650 €2.150 €3.060 €4.550', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 11),
  ('MON-0024', NULL, 'INT-BW', 'Γυναικολογικές €100 €210 €800 €1.200 €1.650 €2.350 €3.500 Θωρακοχειρουργικές – – €1.040 €1.650 €2.150 €3.060 €4.550 Καρδιοχειρουργικές – – €1.040 €1.650 €2.150 €3.060 €4.550', 'Βιβλίο όρων bewell_εκδ.4.1_03-2025.pdf', 11),
