INSERT INTO knowledge.document_page (document_id, page_number, content, source_filename, extraction_method, quality_flag, content_sha256) VALUES ('DOC-GRO-SP-06', 9, 'Επιπλέον παροχές (2)
Ενήλικες Παιδιά 
Δωρεάν μεταφορά με ασθενοφόρο στις κλινικές του ομίλου της 
Βιοϊατρικής √ -
Δωρεάν διαγνωστικές εξετάσεις έως € 300, στα Τμήματα 
επειγόντων περιστατικών των κλινικών του Ομίλου Βιοϊατρική με 
την προϋπόθεση νοσηλείας
√ -
Έκπτωση 10% στην προσωπική επιβάρυνση του ασφαλισμένου 
(συμμετοχή) στον ασφαλισμένο με ατομικό ή ομαδικό 
ασφαλιστήριο συμβόλαιο, σε περίπτωση νοσηλείας σε κλινική του 
ομίλου ΒΙΟΙΑΤΡΙΚΗ και ανώτατο όριο τα 500€
√ -
Έκπτωση 10% για κατ’ οίκον νοσηλεία στα έξοδα για ιατρικό και 
νοσηλευτικό προσωπικό, στην Αθήνα, Πειραιά και Θεσσαλονίκη √ √', 'Sante-Primaire-2019-Customer(1).pdf', 'pypdf', NULL, '7f7163f9b9164c2d1be682aff8a1a2e3a4bd4fe73ad55b77fe02cf11d2f42e7c')
