INSERT INTO knowledge.document_page (document_id, page_number, content, source_filename, extraction_method, quality_flag, content_sha256) VALUES ('DOC-INT-BW-01', 33, '19.8 Επίδομα αποθεραπείας σε Κέντρο Αποκ ατάστασης
