INSERT INTO knowledge.document_chunk (chunk_id, document_id, chunk_ordinal, page_start, page_end, content, content_sha256) VALUES ('74c5a0ba-84fa-551d-a98a-f2a36e6504f9', 'DOC-GRO-SPR-05', 1, 1, 1, 'για θεραπεία botox 
