INSERT INTO knowledge.document_chunk (chunk_id, document_id, chunk_ordinal, page_start, page_end, content, content_sha256) VALUES ('16308fca-f249-5de2-85ac-4c8fe126a505', 'DOC-GEN-MF-03', 6, 5, 5, '37
