INSERT INTO recommendation.scoring_rule (
  rule_id, ruleset_id, rule_code, description, priority, rule_kind,
  conditions, outcome, source_note, human_approved
)
SELECT
  md5(os.question_id || '|' || os.option_value || '|' || os.signal_code)::uuid,
  '22222222-2222-4222-8222-222222222222'::uuid,
  'IM-' || upper(replace(os.question_id, 'Q_', '')) || '-' || upper(replace(os.option_value, '_', '-')) || '-' || upper(replace(os.signal_code, '_', '-')),
  coalesce(os.reason_template, os.question_id || ' → ' || os.option_value || ' → ' || os.signal_code),
  100,
  CASE sd.signal_kind WHEN 'warning_only' THEN 'warning' WHEN 'filter' THEN 'eligibility' ELSE 'score' END,
  jsonb_build_object('question_id', os.question_id, 'option_value', os.option_value),
  jsonb_build_object('signal_code', os.signal_code, 'weight', os.weight),
  'InsuranceMarket Final Advisory Flow 105:2',
  false
FROM recommendation.option_signal os
JOIN recommendation.signal_definition sd USING (signal_code)
WHERE os.status = 'draft'
ON CONFLICT (ruleset_id, rule_code) DO UPDATE SET
  description = EXCLUDED.description,
  priority = EXCLUDED.priority,
  rule_kind = EXCLUDED.rule_kind,
  conditions = EXCLUDED.conditions,
  outcome = EXCLUDED.outcome,
  source_note = EXCLUDED.source_note,
  human_approved = EXCLUDED.human_approved;

INSERT INTO catalog.evaluation_mapping (
  mapping_id, question_text, answer_signal, database_dimensions, action_text,
  is_active, question_id, option_value, signal_code, weight,
  mapping_status, requires_human_approval, metadata
)
SELECT
  'IM-MAP-' || lpad(row_number() OVER (ORDER BY q.display_order, o.display_order, os.signal_code)::text, 3, '0'),
  q.question_text,
  o.label,
  sd.database_dimensions::text,
  CASE sd.signal_kind WHEN 'warning_only' THEN 'Warning / advisor confirmation' ELSE 'Deterministic score input' END,
  true,
  q.question_id,
  os.option_value,
  os.signal_code,
  os.weight,
  'draft',
  true,
  jsonb_build_object('reason_template', os.reason_template)
FROM recommendation.option_signal os
JOIN intake.question q USING (question_id)
JOIN intake.question_option o
  ON o.question_id = os.question_id AND o.value = to_jsonb(os.option_value)
JOIN recommendation.signal_definition sd USING (signal_code)
WHERE q.is_active AND o.is_active
ON CONFLICT (mapping_id) DO UPDATE SET
  question_text = EXCLUDED.question_text,
  answer_signal = EXCLUDED.answer_signal,
  database_dimensions = EXCLUDED.database_dimensions,
  action_text = EXCLUDED.action_text,
  is_active = EXCLUDED.is_active,
  question_id = EXCLUDED.question_id,
  option_value = EXCLUDED.option_value,
  signal_code = EXCLUDED.signal_code,
  weight = EXCLUDED.weight,
  mapping_status = EXCLUDED.mapping_status,
  requires_human_approval = EXCLUDED.requires_human_approval,
  metadata = EXCLUDED.metadata;

INSERT INTO catalog.data_quality_issue (
