) VALUES
  ('DQ-010', 'Recommendation scoring', 'Draft signal mappings are not human-approved', 'The aligned mappings were generated for POC integration.', 'Product/compliance owner must approve each option signal and product signal before production.', 'Κρίσιμη', 'open'),
  ('DQ-011', 'Smart Budget Choice', 'No current premium dataset', 'The current knowledge base contains terms and historical monetary excerpts, not live quotes.', 'Use a current pricing/quotation source; until then label budget ranking as a deductible-and-coverage proxy.', 'Κρίσιμη', 'open'),
  ('DQ-012', 'Immediate use', 'Missing data cannot prove immediate eligibility', 'Waiting-period coverage is incomplete or variant-specific.', 'Show a warning and confirm waiting periods for the exact policy variant.', 'Κρίσιμη', 'open'),
