-- BEGIN 013_seed_draft_product_signals.sql
BEGIN;

DELETE FROM recommendation.product_signal
WHERE source_method = 'generated_draft_v1';

-- These rows are deterministic POC signals derived from the existing structured corpus.
-- They remain draft and human_approved=false until reviewed by product/compliance owners.

INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  c.product_id,
  'private_hospitals',
  least(100, 78 + least(c.network_count, 4) * 5)::numeric(6,2),
  CASE WHEN c.network_count > 0 THEN 'medium' ELSE 'low' END,
  'Keyword evidence for private/cooperating hospitals plus network presence.',
  recommendation.collect_evidence(c.product_id, ARRAY['ιδιωτικ', 'νοσοκομ', 'συνεργαζομεν'], 5),
  'generated_draft_v1', 'draft', false
FROM recommendation.product_evidence_corpus c
WHERE c.corpus LIKE ANY (ARRAY['%ιδιωτικ%νοσοκομ%', '%συνεργαζομεν%νοσοκομ%', '%νοσοκομειακ%']);

INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  c.product_id,
  'low_deductible',
  CASE
    WHEN c.corpus ~ '(μηδενικ[^.]{0,50}(απαλλαγ|συμμετοχ)|0%[^.]{0,40}(συμμετοχ|απαλλαγ)|χωρις συμμετοχ)' THEN 95
    WHEN c.corpus ~ '(χαμηλ[^.]{0,50}(απαλλαγ|συμμετοχ)|10%|20%)' THEN 75
    ELSE 50
  END::numeric(6,2),
  'low',
  'Text-derived deductible indicator; exact policy variant and monetary amount must be confirmed.',
  recommendation.collect_evidence(c.product_id, ARRAY['απαλλαγ', 'συμμετοχ', '0%', '10%', '20%'], 5),
  'generated_draft_v1', 'draft', false
FROM recommendation.product_evidence_corpus c
WHERE c.deductible_count > 0
   OR c.corpus LIKE ANY (ARRAY['%απαλλαγ%', '%συμμετοχ%']);

INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  c.product_id,
  'deductible_flexibility',
  CASE WHEN c.deductible_count >= 4 THEN 85
       WHEN c.deductible_count >= 2 THEN 72
       ELSE 55 END::numeric(6,2),
  'low',
  'Relative count of documented deductible/copayment rules; this does not imply lower premium.',
  recommendation.collect_evidence(c.product_id, ARRAY['απαλλαγ', 'συμμετοχ'], 5),
  'generated_draft_v1', 'draft', false
FROM recommendation.product_evidence_corpus c
WHERE c.deductible_count > 0;

