INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  c.product_id,
  'provider_freedom',
  least(85, 50 + least(c.network_count, 7) * 5)::numeric(6,2),
  'low',
  'Network-presence proxy only; network size is not equivalent to unrestricted provider choice.',
  recommendation.collect_evidence(c.product_id, ARRAY['δικτυ', 'συνεργαζομεν', 'επιλογ'], 5),
