FROM recommendation.product_evidence_corpus c
WHERE c.network_count > 0
   OR c.corpus LIKE ANY (ARRAY['%δικτυ%', '%συνεργαζομεν%', '%ελευθερ%επιλογ%']);

INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  c.product_id,
  'low_bureaucracy',
  72::numeric(6,2),
  'low',
  'Operational-process proxy from direct settlement/payment or coordinated network use.',
  recommendation.collect_evidence(c.product_id, ARRAY['απευθειας', 'διακανονισ', 'τηλεφωνικ κεντρ', 'προεγκρισ'], 5),
  'generated_draft_v1', 'draft', false
FROM recommendation.product_evidence_corpus c
WHERE c.corpus LIKE ANY (ARRAY['%απευθειας%καταβολ%', '%απευθειας%πληρωμ%', '%διακανονισ%', '%τηλεφωνικ%κεντρ%', '%προεγκρισ%']);

-- Immediate-use sensitivity is intentionally populated only when the corpus explicitly states no waiting.
INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  c.product_id,
  'waiting_period_sensitivity',
  82::numeric(6,2),
  'low',
  'Explicit no-waiting phrase found. Exact coverage and policy variant still require confirmation.',
  recommendation.collect_evidence(c.product_id, ARRAY['χωρις περιοδο αναμον', 'χωρις αναμον'], 5),
  'generated_draft_v1', 'draft', false
FROM recommendation.product_evidence_corpus c
WHERE c.corpus LIKE ANY (ARRAY['%χωρις περιοδο αναμον%', '%χωρις αναμον%']);

-- Personal continuity is an intent fit, not a coverage claim. It applies weakly to active individual products.
INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  p.product_id,
  'continuity_independent',
  60::numeric(6,2),
  'low',
  'Active individual-product scope only; continuity terms and eligibility require advisor confirmation.',
  '[]'::jsonb,
  'generated_draft_v1', 'draft', false
FROM catalog.product p
WHERE p.is_active AND p.recommendation_scope;

-- Composite segment signals. These are relative POC indicators, not premiums, offers or underwriting decisions.
INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  p.product_id,
  'maximum_protection',
  round(avg(ps.score)::numeric, 2),
  'low',
  'Average of documented core coverage signals; not a statement of completeness.',
  coalesce(jsonb_agg(jsonb_build_object('signal_code', ps.signal_code, 'score', ps.score, 'evidence', ps.evidence)), '[]'::jsonb),
  'generated_draft_v1', 'draft', false
FROM catalog.product p
JOIN recommendation.product_signal ps ON ps.product_id = p.product_id
WHERE ps.source_method = 'generated_draft_v1'
  AND ps.signal_code IN ('private_hospitals', 'outpatient', 'major_hospitalization', 'emergency', 'international', 'prevention')
GROUP BY p.product_id
HAVING count(*) >= 3;

INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  p.product_id,
  'balanced_value',
  round(avg(ps.score)::numeric, 2),
  'low',
  'Relative mix of core coverage and deductible flexibility; no live premium data is used.',
  coalesce(jsonb_agg(jsonb_build_object('signal_code', ps.signal_code, 'score', ps.score, 'evidence', ps.evidence)), '[]'::jsonb),
  'generated_draft_v1', 'draft', false
FROM catalog.product p
JOIN recommendation.product_signal ps ON ps.product_id = p.product_id
WHERE ps.source_method = 'generated_draft_v1'
  AND ps.signal_code IN ('private_hospitals', 'outpatient', 'major_hospitalization', 'deductible_flexibility')
GROUP BY p.product_id
HAVING count(*) >= 2;

INSERT INTO recommendation.product_signal (
  product_id, signal_code, score, confidence, basis, evidence,
  source_method, status, human_approved
)
SELECT
  p.product_id,
  'essential_budget',
  round(avg(ps.score)::numeric, 2),
  'low',
  'Coverage-and-deductible proxy only. It must not be described as the cheapest product.',
  coalesce(jsonb_agg(jsonb_build_object('signal_code', ps.signal_code, 'score', ps.score, 'evidence', ps.evidence)), '[]'::jsonb),
  'generated_draft_v1', 'draft', false
FROM catalog.product p
JOIN recommendation.product_signal ps ON ps.product_id = p.product_id
WHERE ps.source_method = 'generated_draft_v1'
  AND ps.signal_code IN ('major_hospitalization', 'private_hospitals', 'deductible_flexibility')
GROUP BY p.product_id
HAVING count(*) >= 2;

COMMIT;
-- END 013_seed_draft_product_signals.sql

-- BEGIN 014_assessment_and_recommendation_functions.sql
BEGIN;

CREATE OR REPLACE FUNCTION intake.try_date(p_value text)
RETURNS date
LANGUAGE plpgsql
IMMUTABLE
STRICT
AS $$
BEGIN
  RETURN p_value::date;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION intake.validate_assessment_payload(p_answers jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = pg_catalog, intake
AS $$
DECLARE
  v_errors jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_value text;
  v_array jsonb;
  v_item jsonb;
  v_birth_text text;
  v_birth_date date;
  v_expected_min integer := 1;
  v_upload jsonb;
BEGIN
  IF p_answers IS NULL OR jsonb_typeof(p_answers) <> 'object' THEN
    RETURN jsonb_build_object(
      'valid', false,
      'schema_version', 'im-health-assessment-2026-07-v1',
      'errors', jsonb_build_array(jsonb_build_object('field', '$', 'code', 'invalid_payload', 'message', 'Το assessment payload πρέπει να είναι JSON object.')),
      'warnings', '[]'::jsonb
    );
  END IF;

  v_value := coalesce(p_answers->>'insured_people', p_answers->>'insuredPeople');
  IF v_value IS NULL OR v_value NOT IN ('self', 'self_spouse', 'family', 'child') THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'insured_people', 'code', 'invalid_value', 'message', 'Μη έγκυρη σύνθεση ασφαλιζομένων.'));
  ELSE
    v_expected_min := CASE WHEN v_value IN ('self_spouse', 'family') THEN 2 ELSE 1 END;
  END IF;

  v_array := coalesce(p_answers->'birth_dates', p_answers->'birthDates');
  IF v_array IS NULL OR jsonb_typeof(v_array) <> 'array' OR jsonb_array_length(v_array) < v_expected_min THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'birth_dates', 'code', 'missing_or_incomplete', 'message', 'Απαιτείται έγκυρη ημερομηνία γέννησης για κάθε ασφαλιζόμενο.'));
  ELSE
    FOR v_item IN SELECT value FROM jsonb_array_elements(v_array)
    LOOP
      v_birth_text := coalesce(v_item->>'birth_date', v_item->>'birthDate', v_item->>'date');
      v_birth_date := intake.try_date(v_birth_text);
      IF v_birth_date IS NULL OR v_birth_date > current_date OR v_birth_date < date '1900-01-01' THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'birth_dates', 'code', 'invalid_date', 'message', 'Μία ημερομηνία γέννησης δεν είναι έγκυρη.'));
      END IF;
    END LOOP;
  END IF;

  v_value := coalesce(p_answers->>'existing_insurance', p_answers->>'existingInsurance');
  IF v_value IS NULL OR v_value NOT IN ('none', 'individual', 'employer_group', 'individual_and_group') THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'existing_insurance', 'code', 'invalid_value', 'message', 'Μη έγκυρη απάντηση υπάρχουσας ασφάλισης.'));
  END IF;

  v_value := coalesce(p_answers->>'evaluation_goal', p_answers->>'evaluationGoal');
  IF v_value IS NULL OR v_value NOT IN ('first_time', 'independent_from_employer', 'evaluate_existing', 'improve_value') THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'evaluation_goal', 'code', 'invalid_value', 'message', 'Μη έγκυρος στόχος αξιολόγησης.'));
  END IF;

  v_array := coalesce(p_answers->'priorities', '[]'::jsonb);
  IF jsonb_typeof(v_array) <> 'array' OR jsonb_array_length(v_array) < 1 OR jsonb_array_length(v_array) > 3 THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'priorities', 'code', 'selection_count', 'message', 'Επίλεξε από 1 έως 3 προτεραιότητες.'));
  ELSE
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(v_array) x(value)
      WHERE value NOT IN ('private_hospitals', 'low_or_zero_deductible', 'outpatient_doctors_diagnostics', 'major_hospitalization', 'emergency', 'prevention_checkup', 'international', 'pediatric')
    ) THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'priorities', 'code', 'invalid_value', 'message', 'Υπάρχει μη έγκυρη προτεραιότητα.'));
    END IF;
    IF (SELECT count(*) FROM jsonb_array_elements_text(v_array)) <> (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(v_array) x(value)) THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'priorities', 'code', 'duplicate_value', 'message', 'Οι προτεραιότητες δεν πρέπει να επαναλαμβάνονται.'));
    END IF;
  END IF;

  v_value := coalesce(p_answers->>'deductible_preference', p_answers->>'deductiblePreference');
  IF v_value IS NULL OR v_value NOT IN ('minimum', 'balanced', 'higher_for_lower_premium') THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'deductible_preference', 'code', 'invalid_value', 'message', 'Μη έγκυρη προτίμηση απαλλαγής.'));
  END IF;

  v_value := coalesce(p_answers->>'protection_cost', p_answers->>'protectionCost');
  IF v_value IS NULL OR v_value NOT IN ('maximum_protection', 'balanced', 'essential_lower_cost') THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'protection_cost', 'code', 'invalid_value', 'message', 'Μη έγκυρη προσέγγιση προστασίας και κόστους.'));
  END IF;

  v_array := coalesce(p_answers->'additional_needs', p_answers->'additionalNeeds', '[]'::jsonb);
  IF jsonb_typeof(v_array) <> 'array' THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'additional_needs', 'code', 'invalid_type', 'message', 'Οι πρόσθετες ανάγκες πρέπει να είναι λίστα.'));
  ELSIF EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(v_array) x(value)
    WHERE value NOT IN ('frequent_travel', 'immediate_use', 'maternity', 'young_children', 'physiotherapy', 'prevention_checkup', 'provider_freedom', 'low_bureaucracy')
  ) THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'additional_needs', 'code', 'invalid_value', 'message', 'Υπάρχει μη έγκυρη πρόσθετη ανάγκη.'));
  END IF;

  v_upload := coalesce(p_answers->'existing_policy_upload', p_answers->'existingPolicyUpload', '{}'::jsonb);
  IF jsonb_typeof(v_upload) <> 'object' THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'existing_policy_upload', 'code', 'invalid_type', 'message', 'Τα στοιχεία αρχείου πρέπει να είναι JSON object.'));
  ELSIF v_upload ?| ARRAY['content', 'bytes', 'base64', 'data', 'file_content'] THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('field', 'existing_policy_upload', 'code', 'file_bytes_forbidden', 'message', 'Στη βάση επιτρέπονται μόνο ασφαλή metadata και όχι bytes ή base64 αρχείου.'));
  END IF;

  IF coalesce(p_answers->>'existing_insurance', p_answers->>'existingInsurance') <> 'none'
     AND (v_upload = '{}'::jsonb OR coalesce(v_upload->>'filename', '') = '') THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('field', 'existing_policy_upload', 'code', 'comparison_limited', 'message', 'Χωρίς το υπάρχον έγγραφο, η σύγκριση θα είναι περιορισμένη και θα απαιτήσει επιβεβαίωση από σύμβουλο.'));
  END IF;

  IF coalesce(p_answers->'additional_needs', p_answers->'additionalNeeds', '[]'::jsonb) ? 'immediate_use' THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('field', 'additional_needs', 'code', 'waiting_period_confirmation', 'message', 'Η άμεση χρήση δεν μπορεί να επιβεβαιωθεί χωρίς έλεγχο των περιόδων αναμονής του ακριβούς προγράμματος.'));
  END IF;

  RETURN jsonb_build_object(
    'valid', jsonb_array_length(v_errors) = 0,
    'schema_version', 'im-health-assessment-2026-07-v1',
    'errors', v_errors,
    'warnings', v_warnings
  );
END;
$$;

CREATE OR REPLACE FUNCTION intake.upsert_assessment_submission(
  p_session_id uuid,
  p_answers jsonb,
  p_generated_profile jsonb DEFAULT '{}'::jsonb,
  p_upload_metadata jsonb DEFAULT '{}'::jsonb,
  p_status text DEFAULT 'completed'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, intake
AS $$
DECLARE
  v_validation jsonb;
  v_submission_id uuid;
BEGIN
  v_validation := intake.validate_assessment_payload(p_answers);
  IF NOT coalesce((v_validation->>'valid')::boolean, false) THEN
    RAISE EXCEPTION 'Invalid assessment payload: %', v_validation->'errors'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO intake.assessment_submission (
    session_id, schema_version, answers, generated_profile, upload_metadata,
    status, completed_at
  ) VALUES (
    p_session_id,
    'im-health-assessment-2026-07-v1',
    p_answers,
    coalesce(p_generated_profile, '{}'::jsonb),
    coalesce(p_upload_metadata, '{}'::jsonb),
    p_status,
    CASE WHEN p_status = 'completed' THEN now() ELSE NULL END
  )
  ON CONFLICT (session_id) DO UPDATE SET
    schema_version = EXCLUDED.schema_version,
    answers = EXCLUDED.answers,
    generated_profile = EXCLUDED.generated_profile,
    upload_metadata = EXCLUDED.upload_metadata,
    status = EXCLUDED.status,
    completed_at = EXCLUDED.completed_at,
    updated_at = now()
  RETURNING submission_id INTO v_submission_id;

  RETURN v_submission_id;
END;
$$;

CREATE OR REPLACE FUNCTION recommendation.extract_submission_signals(p_answers jsonb)
RETURNS TABLE (
  signal_code text,
  user_weight numeric,
  source_answers jsonb
)
LANGUAGE sql
STABLE
SET search_path = pg_catalog, intake, recommendation
AS $$
  WITH scalar_selected(question_id, option_value) AS (
    SELECT * FROM (VALUES
      ('Q_INSURED_PEOPLE'::text, coalesce(p_answers->>'insured_people', p_answers->>'insuredPeople')),
      ('Q_EXISTING_INSURANCE'::text, coalesce(p_answers->>'existing_insurance', p_answers->>'existingInsurance')),
      ('Q_EVALUATION_GOAL'::text, coalesce(p_answers->>'evaluation_goal', p_answers->>'evaluationGoal')),
      ('Q_DEDUCTIBLE_PREFERENCE'::text, coalesce(p_answers->>'deductible_preference', p_answers->>'deductiblePreference')),
      ('Q_PROTECTION_COST'::text, coalesce(p_answers->>'protection_cost', p_answers->>'protectionCost'))
    ) v(question_id, option_value)
    WHERE option_value IS NOT NULL
  ),
  priority_selected AS (
    SELECT 'Q_PRIORITIES'::text AS question_id, value AS option_value
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(coalesce(p_answers->'priorities', '[]'::jsonb)) = 'array'
        THEN coalesce(p_answers->'priorities', '[]'::jsonb) ELSE '[]'::jsonb END
    ) x(value)
  ),
  need_selected AS (
    SELECT 'Q_ADDITIONAL_NEEDS'::text AS question_id, value AS option_value
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(coalesce(p_answers->'additional_needs', p_answers->'additionalNeeds', '[]'::jsonb)) = 'array'
        THEN coalesce(p_answers->'additional_needs', p_answers->'additionalNeeds', '[]'::jsonb) ELSE '[]'::jsonb END
    ) x(value)
  ),
  selected AS (
    SELECT * FROM scalar_selected
    UNION ALL SELECT * FROM priority_selected
    UNION ALL SELECT * FROM need_selected
  ),
  mapped AS (
    SELECT
      os.signal_code,
      os.weight AS user_weight,
      jsonb_build_object('question_id', s.question_id, 'option_value', s.option_value, 'reason', os.reason_template) AS source_answer
    FROM selected s
    JOIN recommendation.option_signal os
      ON os.question_id = s.question_id AND os.option_value = s.option_value
    WHERE os.status <> 'retired'
  ),
  birth_dates AS (
    SELECT intake.try_date(coalesce(item->>'birth_date', item->>'birthDate', item->>'date')) AS birth_date
    FROM jsonb_array_elements(
      CASE WHEN jsonb_typeof(coalesce(p_answers->'birth_dates', p_answers->'birthDates', '[]'::jsonb)) = 'array'
        THEN coalesce(p_answers->'birth_dates', p_answers->'birthDates', '[]'::jsonb) ELSE '[]'::jsonb END
    ) item
  ),
  derived_pediatric AS (
    SELECT
      'pediatric'::text AS signal_code,
      0.80::numeric AS user_weight,
      jsonb_build_object('question_id', 'Q_BIRTH_DATES', 'derived', 'at_least_one_minor') AS source_answer
    WHERE EXISTS (
      SELECT 1 FROM birth_dates
      WHERE birth_date IS NOT NULL AND birth_date > (current_date - interval '18 years')::date
    )
  ),
  all_signals AS (
    SELECT * FROM mapped
    UNION ALL
    SELECT * FROM derived_pediatric
  )
  SELECT
    a.signal_code,
    round(sum(a.user_weight)::numeric, 4) AS user_weight,
    jsonb_agg(a.source_answer) AS source_answers
  FROM all_signals a
  GROUP BY a.signal_code;
$$;

CREATE OR REPLACE FUNCTION recommendation.score_submission(
  p_answers jsonb,
  p_allow_draft boolean DEFAULT false
)
RETURNS TABLE (
  product_id text,
  product_name text,
  company_name text,
  best_match_score numeric,
  premium_choice_score numeric,
  smart_budget_score numeric,
  matched_signals jsonb,
  missing_signals jsonb,
  evidence jsonb,
  warnings jsonb
)
LANGUAGE sql
STABLE
SET search_path = pg_catalog, catalog, recommendation
AS $$
  WITH user_signals AS (
    SELECT es.signal_code, es.user_weight, es.source_answers, sd.signal_kind, sd.name AS signal_name
    FROM recommendation.extract_submission_signals(p_answers) es
    JOIN recommendation.signal_definition sd USING (signal_code)
    WHERE sd.status <> 'retired'
  ),
  scoring_signals AS (
    SELECT * FROM user_signals WHERE signal_kind IN ('score', 'segment') AND user_weight > 0
  ),
  products AS (
    SELECT p.product_id, p.name AS product_name, c.name AS company_name
    FROM catalog.product p
    JOIN catalog.company c USING (company_id)
    WHERE p.is_active AND p.recommendation_scope
  ),
  matrix AS (
    SELECT
      p.product_id,
      p.product_name,
      p.company_name,
      us.signal_code,
      us.signal_name,
      us.user_weight,
      us.source_answers,
      ps.score AS product_signal_score,
      ps.confidence,
      ps.basis,
      ps.evidence AS signal_evidence,
      ps.human_approved
    FROM products p
    CROSS JOIN scoring_signals us
    LEFT JOIN recommendation.product_signal ps
      ON ps.product_id = p.product_id
     AND ps.signal_code = us.signal_code
     AND ps.status <> 'retired'
     AND (p_allow_draft OR ps.human_approved)
  ),
  base AS (
    SELECT
      m.product_id,
      m.product_name,
      m.company_name,
      round((100 * sum(m.user_weight * coalesce(m.product_signal_score, 0)) / nullif(sum(m.user_weight * 100), 0))::numeric, 2) AS base_score,
      coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'signal_code', m.signal_code,
        'signal_name', m.signal_name,
        'user_weight', m.user_weight,
        'product_score', m.product_signal_score,
        'confidence', m.confidence,
        'basis', m.basis,
        'source_answers', m.source_answers
      )) ORDER BY m.user_weight DESC, m.signal_code) FILTER (WHERE m.product_signal_score IS NOT NULL), '[]'::jsonb) AS matched_signals,
      coalesce(jsonb_agg(jsonb_build_object(
        'signal_code', m.signal_code,
        'signal_name', m.signal_name,
        'user_weight', m.user_weight
      ) ORDER BY m.user_weight DESC, m.signal_code) FILTER (WHERE m.product_signal_score IS NULL), '[]'::jsonb) AS missing_signals,
      coalesce(jsonb_agg(jsonb_build_object(
        'signal_code', m.signal_code,
        'evidence', m.signal_evidence
      ) ORDER BY m.user_weight DESC, m.signal_code) FILTER (WHERE m.product_signal_score IS NOT NULL AND jsonb_array_length(m.signal_evidence) > 0), '[]'::jsonb) AS evidence,
      bool_or(coalesce(m.human_approved, false) = false AND m.product_signal_score IS NOT NULL) AS uses_unapproved_signal
    FROM matrix m
    GROUP BY m.product_id, m.product_name, m.company_name
  ),
  segment_scores AS (
    SELECT
      p.product_id,
      max(ps.score) FILTER (WHERE ps.signal_code = 'maximum_protection') AS maximum_protection_score,
      max(ps.score) FILTER (WHERE ps.signal_code = 'balanced_value') AS balanced_value_score,
      max(ps.score) FILTER (WHERE ps.signal_code = 'essential_budget') AS essential_budget_score
    FROM products p
    LEFT JOIN recommendation.product_signal ps
      ON ps.product_id = p.product_id
     AND ps.status <> 'retired'
     AND (p_allow_draft OR ps.human_approved)
    GROUP BY p.product_id
  ),
  flags AS (
    SELECT
      EXISTS (SELECT 1 FROM user_signals WHERE signal_code = 'waiting_period_sensitivity') AS needs_immediate_use_check,
      EXISTS (SELECT 1 FROM user_signals WHERE signal_code = 'existing_policy_comparison') AS needs_existing_policy_comparison,
      EXISTS (SELECT 1 FROM user_signals WHERE signal_code = 'essential_budget') AS budget_oriented
  )
  SELECT
    b.product_id,
    b.product_name,
    b.company_name,
    b.base_score AS best_match_score,
    round((0.70 * b.base_score + 0.30 * coalesce(s.maximum_protection_score, b.base_score))::numeric, 2) AS premium_choice_score,
    round((0.65 * b.base_score + 0.35 * coalesce(s.essential_budget_score, b.base_score))::numeric, 2) AS smart_budget_score,
    b.matched_signals,
    b.missing_signals,
    b.evidence,
    jsonb_build_array(
      jsonb_build_object('code', 'demo_only', 'message', 'Προσωρινή deterministic demo αξιολόγηση. Δεν αποτελεί ασφαλιστική προσφορά, underwriting ή δεσμευτική συμβουλή.'),
      jsonb_build_object('code', 'human_review_required', 'message', 'Οι όροι, οι αναμονές, οι απαλλαγές, τα όρια και η επιλεξιμότητα χρειάζονται επιβεβαίωση από εξουσιοδοτημένο σύμβουλο.')
    )
    || CASE WHEN p_allow_draft OR b.uses_unapproved_signal THEN jsonb_build_array(jsonb_build_object('code', 'draft_signals', 'message', 'Η κατάταξη χρησιμοποιεί μη εγκεκριμένα draft signals για POC.')) ELSE '[]'::jsonb END
    || CASE WHEN jsonb_array_length(b.missing_signals) > 0 THEN jsonb_build_array(jsonb_build_object('code', 'missing_evidence', 'message', 'Δεν υπάρχει επαρκές δομημένο evidence για όλα τα επιλεγμένα κριτήρια.')) ELSE '[]'::jsonb END
    || CASE WHEN f.needs_immediate_use_check THEN jsonb_build_array(jsonb_build_object('code', 'waiting_period_check', 'message', 'Η άμεση χρήση απαιτεί ρητό έλεγχο περιόδων αναμονής για το ακριβές πρόγραμμα.')) ELSE '[]'::jsonb END
    || CASE WHEN f.needs_existing_policy_comparison THEN jsonb_build_array(jsonb_build_object('code', 'existing_policy_check', 'message', 'Η ακριβής σύγκριση απαιτεί το υπάρχον ασφαλιστήριο ή την προσφορά.')) ELSE '[]'::jsonb END
    || CASE WHEN f.budget_oriented THEN jsonb_build_array(jsonb_build_object('code', 'no_live_pricing', 'message', 'Το Smart Budget Choice βασίζεται σε coverage/deductible proxy και όχι σε τρέχουσα τιμή ασφαλίστρου.')) ELSE '[]'::jsonb END AS warnings
  FROM base b
  JOIN segment_scores s USING (product_id)
  CROSS JOIN flags f;
$$;

CREATE OR REPLACE FUNCTION recommendation.preview_recommendations(
  p_answers jsonb,
  p_allow_draft boolean DEFAULT false
)
RETURNS TABLE (
  category_code text,
  category_label text,
  product_id text,
  product_name text,
  company_name text,
  score numeric,
  matched_signals jsonb,
  missing_signals jsonb,
  evidence jsonb,
  warnings jsonb
)
LANGUAGE sql
STABLE
SET search_path = pg_catalog, recommendation
AS $$
  WITH scored AS (
    SELECT * FROM recommendation.score_submission(p_answers, p_allow_draft)
  ),
  best AS (
    SELECT 1 AS category_order, 'best_match'::text AS category_code, 'Best Match'::text AS category_label,
      s.*, s.best_match_score AS category_score
    FROM scored s
    ORDER BY s.best_match_score DESC NULLS LAST, s.product_id
    LIMIT 1
  ),
  premium AS (
    SELECT 2 AS category_order, 'premium_choice'::text AS category_code, 'Premium Choice'::text AS category_label,
      s.*, s.premium_choice_score AS category_score
    FROM scored s
    WHERE NOT EXISTS (SELECT 1 FROM best b WHERE b.product_id = s.product_id)
    ORDER BY s.premium_choice_score DESC NULLS LAST, s.product_id
    LIMIT 1
  ),
  budget AS (
    SELECT 3 AS category_order, 'smart_budget_choice'::text AS category_code, 'Smart Budget Choice'::text AS category_label,
      s.*, s.smart_budget_score AS category_score
    FROM scored s
    WHERE NOT EXISTS (SELECT 1 FROM best b WHERE b.product_id = s.product_id)
      AND NOT EXISTS (SELECT 1 FROM premium p WHERE p.product_id = s.product_id)
    ORDER BY s.smart_budget_score DESC NULLS LAST, s.product_id
    LIMIT 1
  ),
  chosen AS (
    SELECT * FROM best
    UNION ALL SELECT * FROM premium
    UNION ALL SELECT * FROM budget
  )
  SELECT
    c.category_code,
    c.category_label,
    c.product_id,
    c.product_name,
    c.company_name,
    c.category_score AS score,
    c.matched_signals,
    c.missing_signals,
    c.evidence,
    c.warnings
  FROM chosen c
  ORDER BY c.category_order;
$$;

CREATE OR REPLACE FUNCTION app_api.validate_assessment(p_answers jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, intake
AS $$
  SELECT intake.validate_assessment_payload(p_answers);
$$;

CREATE OR REPLACE FUNCTION app_api.preview_demo_recommendations(p_answers jsonb)
RETURNS TABLE (
  category_code text,
  category_label text,
  product_id text,
  product_name text,
  company_name text,
  score numeric,
  matched_signals jsonb,
  missing_signals jsonb,
  evidence jsonb,
  warnings jsonb
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, recommendation
AS $$
  SELECT * FROM recommendation.preview_recommendations(p_answers, true);
$$;

CREATE OR REPLACE FUNCTION app_api.product_detail(p_product_id text, p_allow_draft boolean DEFAULT false)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, catalog, recommendation
AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'product_id', p.product_id,
    'name', p.name,
    'company', c.name,
    'product_type', p.product_type,
    'category', p.category,
    'scope_text', p.scope_text,
    'critical_note', p.critical_note,
    'version_label', p.version_label,
    'effective_from', p.effective_from,
    'effective_to', p.effective_to,
    'signals', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'signal_code', ps.signal_code,
        'name', sd.name,
        'score', ps.score,
        'confidence', ps.confidence,
        'basis', ps.basis,
        'evidence', ps.evidence,
        'human_approved', ps.human_approved
      ) ORDER BY sd.name)
      FROM recommendation.product_signal ps
      JOIN recommendation.signal_definition sd USING (signal_code)
      WHERE ps.product_id = p.product_id
        AND ps.status <> 'retired'
        AND (p_allow_draft OR ps.human_approved)
    ), '[]'::jsonb),
    'data_quality_warning', 'Οι καλύψεις και οι όροι απαιτούν επιβεβαίωση για το ακριβές πρόγραμμα και την τρέχουσα έκδοση.'
  ))
  FROM catalog.product p
  JOIN catalog.company c USING (company_id)
  WHERE p.product_id = p_product_id
    AND p.is_active
    AND p.recommendation_scope;
$$;


CREATE OR REPLACE FUNCTION lead.build_advisor_handoff_summary(
  p_answers jsonb,
  p_generated_profile jsonb,
  p_selected_recommendation jsonb
)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, lead
AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'schema_version', 'advisor-handoff-2026-07-v1',
    'insured_people', coalesce(p_answers->'insured_people', p_answers->'insuredPeople'),
    'birth_dates', coalesce(p_answers->'birth_dates', p_answers->'birthDates', '[]'::jsonb),
    'existing_insurance', coalesce(p_answers->'existing_insurance', p_answers->'existingInsurance'),
    'evaluation_goal', coalesce(p_answers->'evaluation_goal', p_answers->'evaluationGoal'),
    'priorities', coalesce(p_answers->'priorities', '[]'::jsonb),
    'deductible_preference', coalesce(p_answers->'deductible_preference', p_answers->'deductiblePreference'),
    'protection_cost', coalesce(p_answers->'protection_cost', p_answers->'protectionCost'),
    'additional_needs', coalesce(p_answers->'additional_needs', p_answers->'additionalNeeds', '[]'::jsonb),
    'existing_policy_upload_metadata', coalesce(p_answers->'existing_policy_upload', p_answers->'existingPolicyUpload', '{}'::jsonb),
    'insurance_profile', coalesce(p_generated_profile, '{}'::jsonb),
    'selected_recommendation', coalesce(p_selected_recommendation, '{}'::jsonb),
    'advisor_focus', jsonb_build_object(
      'strengths', coalesce(p_selected_recommendation->'matched_signals', '[]'::jsonb),
      'trade_offs', coalesce(p_selected_recommendation->'missing_signals', '[]'::jsonb),
      'items_to_confirm', coalesce(p_selected_recommendation->'warnings', '[]'::jsonb)
    ),
    'generated_at', to_jsonb(now())
  ));
$$;

COMMIT;
-- END 014_assessment_and_recommendation_functions.sql

-- BEGIN 040_supabase_security.sql
BEGIN;

-- Default-deny access. Browser clients must never query intake, recommendation,
-- lead, audit, catalog or knowledge tables directly.
REVOKE ALL ON SCHEMA catalog, knowledge, intake, recommendation, lead, audit, app_api FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA catalog, knowledge, intake, recommendation, lead, audit FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA catalog, knowledge, intake, recommendation, lead, audit FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA catalog, knowledge, intake, recommendation, lead, audit, app_api FROM PUBLIC;

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT schemaname, tablename
    FROM pg_tables
    WHERE schemaname IN ('catalog', 'knowledge', 'intake', 'recommendation', 'lead', 'audit')
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.schemaname, r.tablename);
  END LOOP;
END;
$$;

-- Supabase roles do not exist in the standalone Docker image, so grants are conditional.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'GRANT USAGE ON SCHEMA app_api TO anon';
    EXECUTE 'GRANT EXECUTE ON FUNCTION app_api.assessment_contract() TO anon';
    EXECUTE 'GRANT EXECUTE ON FUNCTION app_api.validate_assessment(jsonb) TO anon';
  END IF;

  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'GRANT USAGE ON SCHEMA app_api TO authenticated';
    EXECUTE 'GRANT EXECUTE ON FUNCTION app_api.assessment_contract() TO authenticated';
    EXECUTE 'GRANT EXECUTE ON FUNCTION app_api.validate_assessment(jsonb) TO authenticated';
  END IF;

  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    EXECUTE 'GRANT USAGE ON SCHEMA catalog, knowledge, intake, recommendation, lead, audit, app_api TO service_role';
    EXECUTE 'GRANT SELECT ON ALL TABLES IN SCHEMA catalog, knowledge TO service_role';
    EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA intake, recommendation, lead TO service_role';
    EXECUTE 'GRANT INSERT, SELECT ON audit.event TO service_role';
    EXECUTE 'GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA catalog, knowledge, intake, recommendation, lead, audit TO service_role';
    EXECUTE 'GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA catalog, knowledge, intake, recommendation, lead, audit, app_api TO service_role';
  END IF;
END;
$$;

COMMENT ON SCHEMA app_api IS
  'Only expose this schema through the Supabase Data API. Sensitive tables remain in unexposed schemas and are accessed server-side with service_role.';

COMMENT ON FUNCTION app_api.preview_demo_recommendations(jsonb) IS
  'Server-only POC function. Uses draft, non-human-approved signals and must never be treated as a production recommendation.';

COMMIT;
-- END 040_supabase_security.sql
